window.DOMANDE = [{"id": "c01-o1", "capitolo": "Cap. 1 – Lo Stato", "giorno": 1, "tipo": "orale", "domanda": "Che cos'è lo Stato e quali sono i suoi elementi costitutivi?", "risposta": "Lo Stato è una forma storica di organizzazione del potere politico che esercita il **monopolio della forza legittima** su un territorio, servendosi di un apparato amministrativo. Gli elementi costitutivi sono tre. Il **popolo** è l'insieme delle persone legate allo Stato dalla **cittadinanza**. Il **territorio** comprende terraferma, mare territoriale e spazio aereo. La **sovranità** è il potere supremo, che ha un aspetto **interno** (comandare sul territorio) e uno **esterno** (indipendenza dagli altri Stati). Come si è detto a lezione, questi elementi **non sono statici**: cambiano nel tempo, per esempio con l'integrazione europea.", "punti_chiave": ["monopolio della forza legittima", "popolo, territorio, sovranità", "sovranità interna ed esterna", "elementi che cambiano nel tempo"]}, {"id": "c01-o2", "capitolo": "Cap. 1 – Lo Stato", "giorno": 1, "tipo": "orale", "domanda": "Che cos'è la legittimazione del potere? Spieghi i tre tipi di Weber.", "risposta": "Il potere politico non si regge solo sulla forza: ha bisogno di essere accettato come giusto, cioè di una **legittimazione**. **Max Weber** ne distingue tre tipi. La legittimazione **tradizionale** viene dall'eredità o dall'investitura, come per il re. Quella **carismatica** viene dalle qualità personali del capo. Quella **legale-razionale** viene dal rispetto di **regole** impersonali ed è legata alla **burocrazia**: è tipica dello Stato moderno e da lei nasce lo **Stato di diritto**. Con la democrazia però le regole non bastano più: serve anche il **consenso popolare**.", "punti_chiave": ["Weber", "tradizionale, carismatica, legale-razionale", "Stato di diritto", "consenso popolare"]}, {"id": "c01-o3", "capitolo": "Cap. 1 – Lo Stato", "giorno": 1, "tipo": "orale", "domanda": "A chi appartiene la sovranità? Quali teorie conosce e che cosa dice l'art. 1 della Costituzione?", "risposta": "Ci sono tre teorie storiche. Per la teoria della **persona giuridica** (Orlando, Romano) il sovrano è lo **Stato stesso**. Per la teoria della **Nazione**, nata con la Rivoluzione francese, la sovranità passa dal re alla Nazione, un'entità astratta. Per la teoria della **sovranità popolare** di **Rousseau** è il popolo a essere sovrano. La nostra Costituzione all'**art. 1** dice che la sovranità **appartiene al popolo**, che la esercita **nelle forme e nei limiti della Costituzione**. Quindi è una sovranità **limitata**: passa per la **rappresentanza**, rispetta la **Costituzione rigida** e i vincoli internazionali ed europei.", "punti_chiave": ["persona giuridica, Nazione, popolo", "Rousseau", "art. 1: nelle forme e nei limiti", "sovranità limitata"]}, {"id": "c01-o4", "capitolo": "Cap. 1 – Lo Stato", "giorno": 1, "tipo": "orale", "domanda": "Come si acquista la cittadinanza italiana?", "risposta": "La cittadinanza è lo status che lega la persona allo Stato e dà **diritti politici** e **doveri**. Si acquista soprattutto per **ius sanguinis**, cioè se si è figli di padre o madre italiani. **Dal 2025** ci sono limiti per chi nasce all'estero e ha un'altra cittadinanza. Lo **ius soli** vale solo in casi eccezionali, per esempio se i genitori sono ignoti o apolidi. Lo straniero **nato in Italia** che ci ha vissuto legalmente fino ai 18 anni può diventare cittadino con una **dichiarazione entro un anno**. Si acquista anche per **matrimonio** o **residenza**. La cittadinanza si può perdere per rinuncia e riacquistare.", "punti_chiave": ["ius sanguinis", "ius soli solo eccezionale", "dichiarazione a 18 anni", "matrimonio e residenza"]}, {"id": "c01-o5", "capitolo": "Cap. 1 – Lo Stato", "giorno": 1, "tipo": "orale", "domanda": "Che cos'è la cittadinanza europea?", "risposta": "La **cittadinanza dell'Unione europea** è stata introdotta dal **Trattato di Maastricht** nel **1992**. Il suo presupposto è essere cittadino di uno Stato membro: è una cittadinanza che **si aggiunge** a quella nazionale e **non la sostituisce**. Dà diritti importanti, prima di tutto quello di **circolare e soggiornare liberamente** negli Stati membri, e anche di votare alle elezioni comunali ed europee nello Stato in cui si risiede.", "punti_chiave": ["Maastricht 1992", "si aggiunge e non sostituisce", "libera circolazione e soggiorno"]}, {"id": "c01-o6", "capitolo": "Cap. 1 – Lo Stato", "giorno": 1, "tipo": "orale", "domanda": "Che cosa sono la potestà pubblica e gli organi costituzionali?", "risposta": "Lo Stato e gli enti pubblici hanno una posizione di **supremazia** sui privati: la **potestà pubblica**, o **potere d'imperio**. Possono incidere sulla sfera giuridica di una persona **anche contro la sua volontà**, come con un esproprio. Questo potere però va esercitato **secondo la legge**, per il **principio di legalità**. Sempre più spesso la PA usa anche strumenti di **diritto privato**, come i contratti. Gli **organi costituzionali** sono quelli **necessari**, la cui struttura è fissata dalla Costituzione: **Parlamento, Governo, Presidente della Repubblica e Corte costituzionale**.", "punti_chiave": ["potere d'imperio", "principio di legalità", "strumenti di diritto privato", "Parlamento, Governo, Presidente, Corte"]}, {"id": "c01-f1", "capitolo": "Cap. 1 – Lo Stato", "giorno": 1, "tipo": "flashcard", "domanda": "Monopolio della forza legittima", "risposta": "Caratteristica dello Stato: solo lo Stato può usare legittimamente la forza (polizia, giustizia) sul suo territorio."}, {"id": "c01-f2", "capitolo": "Cap. 1 – Lo Stato", "giorno": 1, "tipo": "flashcard", "domanda": "Sovranità interna / esterna", "risposta": "Interna: potere supremo di comando sul territorio. Esterna: indipendenza dagli altri Stati."}, {"id": "c01-f3", "capitolo": "Cap. 1 – Lo Stato", "giorno": 1, "tipo": "flashcard", "domanda": "Ius sanguinis", "risposta": "Acquisto della cittadinanza per discendenza: è italiano il figlio di padre o madre italiani (dal 2025 con limiti per chi nasce all'estero)."}, {"id": "c01-f4", "capitolo": "Cap. 1 – Lo Stato", "giorno": 1, "tipo": "flashcard", "domanda": "Ius soli", "risposta": "Acquisto della cittadinanza per nascita sul territorio. In Italia vale solo in casi eccezionali (genitori ignoti o apolidi)."}, {"id": "c01-f5", "capitolo": "Cap. 1 – Lo Stato", "giorno": 1, "tipo": "flashcard", "domanda": "Legittimazione legale-razionale", "risposta": "Tipo di potere (Weber) basato sul rispetto di regole impersonali e sulla burocrazia; base dello Stato di diritto."}, {"id": "c01-f6", "capitolo": "Cap. 1 – Lo Stato", "giorno": 1, "tipo": "flashcard", "domanda": "Potestà d'imperio", "risposta": "Potere della PA di incidere unilateralmente sulla sfera giuridica dei privati, anche contro la loro volontà, nei limiti della legge."}, {"id": "c01-c1", "capitolo": "Cap. 1 – Lo Stato", "giorno": 1, "tipo": "crocette", "domanda": "Quale NON è un elemento costitutivo dello Stato?", "risposta": "Gli elementi sono popolo, territorio e sovranità. Il Regno Unito è uno Stato anche senza una Costituzione scritta.", "opzioni": ["Popolo", "Territorio", "Sovranità", "Costituzione scritta"], "corretta": 3}, {"id": "c01-c2", "capitolo": "Cap. 1 – Lo Stato", "giorno": 1, "tipo": "crocette", "domanda": "Chi ha elaborato la distinzione tra potere tradizionale, carismatico e legale-razionale?", "risposta": "È Max Weber.", "opzioni": ["Hobbes", "Max Weber", "Montesquieu", "Rousseau"], "corretta": 1}, {"id": "c01-c3", "capitolo": "Cap. 1 – Lo Stato", "giorno": 1, "tipo": "crocette", "domanda": "La cittadinanza europea…", "risposta": "È stata introdotta da Maastricht (1992) e si aggiunge alla cittadinanza nazionale.", "opzioni": ["sostituisce quella nazionale", "si aggiunge a quella nazionale", "si acquista solo con la residenza", "è stata creata dal Trattato di Lisbona"], "corretta": 1}, {"id": "c02-o1", "capitolo": "Cap. 2 – Le forme di Stato", "giorno": 1, "tipo": "orale", "domanda": "Che differenza c'è tra forma di Stato e forma di governo?", "risposta": "La **forma di Stato** riguarda il rapporto tra **chi esercita il potere e la società civile**: quali fini persegue lo Stato e quanto spazio lascia alle libertà dei cittadini. La **forma di governo** riguarda invece **come il potere è distribuito tra gli organi costituzionali**, cioè Parlamento, Governo e Capo dello Stato, e i rapporti tra loro. Per esempio l'Italia, come forma di Stato, è uno **Stato di diritto, democratico, pluralista e sociale**, mentre come forma di governo è una **Repubblica parlamentare**.", "punti_chiave": ["rapporto Stato-società", "distribuzione del potere tra organi", "Stato democratico e sociale", "Repubblica parlamentare"]}, {"id": "c02-o2", "capitolo": "Cap. 2 – Le forme di Stato", "giorno": 1, "tipo": "orale", "domanda": "Mi parli dello Stato liberale.", "risposta": "Lo **Stato liberale** nasce tra fine Settecento e Ottocento dalla crisi dello Stato assoluto, quando la borghesia rifiuta il peso fiscale del re (**No taxation without representation**). Le sue caratteristiche sono: una **Costituzione** (Statuto) che riconosce i diritti; il **principio di legalità**, per cui anche il potere rispetta la legge; la **separazione dei poteri**; il **principio rappresentativo**, con parlamentari **senza mandato imperativo**; la **libertà** personale ed economica con il **libero mercato**. Il voto però è riservato a pochi (**Stato monoclasse**) e lo Stato è **minimo**: garantisce solo ordine e sicurezza.", "punti_chiave": ["crisi dello Stato assoluto", "legalità e separazione dei poteri", "Stato monoclasse", "libero mercato e Stato minimo"]}, {"id": "c02-o3", "capitolo": "Cap. 2 – Le forme di Stato", "giorno": 1, "tipo": "orale", "domanda": "Come si passa dallo Stato liberale alla democrazia pluralista?", "risposta": "La **democrazia pluralista** nasce dalla trasformazione dello Stato liberale. Prima di tutto si **allarga la base sociale**: dallo Stato **monoclasse** si passa allo Stato **pluriclasse**, grazie al **suffragio universale** (in Italia quasi universale per gli uomini nel 1912, esteso alle donne nel **1946**). Poi nascono i **partiti di massa** e i **sindacati**, perché il **conflitto sociale** spinge gli operai a organizzarsi. Infine, oltre alle libertà, si riconoscono i **diritti sociali** (salute, istruzione, lavoro). Il prof dice che è più corretto parlare di **democrazia liberale**: non c'è solo il voto, ma anche diritti, pluralismo e separazione dei poteri.", "punti_chiave": ["Stato pluriclasse", "suffragio universale", "partiti di massa", "diritti sociali", "democrazia liberale"]}, {"id": "c02-o4", "capitolo": "Cap. 2 – Le forme di Stato", "giorno": 1, "tipo": "orale", "domanda": "Che cos'è lo Stato sociale e perché è entrato in crisi?", "risposta": "Lo **Stato sociale**, o Welfare State, nasce per **ridurre le disuguaglianze** e tenere insieme società divise dal conflitto di classe. È un **compromesso tra mercato e Stato**: il mercato resta, ma viene **corretto** con interventi pubblici, secondo le idee di **Keynes**, e si crea un'**economia mista**. Dagli **anni '80** entra in crisi: la spesa pubblica cresce troppo (**crisi fiscale dello Stato**), arrivano la globalizzazione e i **vincoli europei** su deficit e debito. La risposta è lo **Stato sociale competitivo**, con meno prestazioni universali, più responsabilità individuale e la **sussidiarietà**, verticale e orizzontale.", "punti_chiave": ["Welfare State", "compromesso mercato-Stato e Keynes", "crisi fiscale", "vincoli europei", "sussidiarietà"]}, {"id": "c02-o5", "capitolo": "Cap. 2 – Le forme di Stato", "giorno": 1, "tipo": "orale", "domanda": "Che differenza c'è tra Stato federale e Stato regionale?", "risposta": "Sono entrambi **Stati composti**, in cui il potere è diviso tra centro ed enti territoriali. Nello **Stato federale** gli Stati membri hanno una **propria Costituzione**, c'è un Parlamento con una **Camera che rappresenta gli Stati** e gli Stati partecipano alla revisione costituzionale. Di solito nasce da un **patto** tra Stati prima indipendenti (come gli USA). Nello **Stato regionale**, come l'Italia, le Regioni hanno **Statuti e non Costituzioni**, hanno **autonomia ma non sovranità**, non c'è una Camera delle Regioni e i conflitti li risolve la **Corte costituzionale**. Il percorso è inverso: lo Stato **cede** poteri verso il basso.", "punti_chiave": ["Stato composto", "Costituzioni degli Stati membri", "Camera degli Stati", "autonomia e non sovranità", "Corte costituzionale"]}, {"id": "c02-o6", "capitolo": "Cap. 2 – Le forme di Stato", "giorno": 1, "tipo": "orale", "domanda": "Come sono regolati i rapporti tra Stato e Chiesa in Italia?", "risposta": "L'Italia ha scelto un **regime concordatario**. L'**art. 7** dice che Stato e Chiesa cattolica sono, **ciascuno nel proprio ordine, indipendenti e sovrani**, e che i rapporti sono regolati dai **Patti Lateranensi** del 1929. Se le modifiche sono accettate da entrambe le parti, **non serve una revisione costituzionale**. Con l'**Accordo di Villa Madama (1984)** il cattolicesimo **non è più religione di Stato**. L'**art. 8** stabilisce che tutte le confessioni sono **egualmente libere** e possono stipulare **intese** con lo Stato. L'Italia è quindi uno **Stato laico**, che garantisce la libertà religiosa di tutti.", "punti_chiave": ["regime concordatario", "art. 7 e Patti Lateranensi", "Villa Madama 1984", "art. 8 e intese", "laicità"]}, {"id": "c02-f1", "capitolo": "Cap. 2 – Le forme di Stato", "giorno": 1, "tipo": "flashcard", "domanda": "Forma di Stato", "risposta": "Rapporto tra chi esercita il potere e la società civile (fini dello Stato, libertà dei cittadini)."}, {"id": "c02-f2", "capitolo": "Cap. 2 – Le forme di Stato", "giorno": 1, "tipo": "flashcard", "domanda": "Forma di governo", "risposta": "Modo in cui il potere è distribuito tra gli organi costituzionali (Parlamento, Governo, Capo dello Stato)."}, {"id": "c02-f3", "capitolo": "Cap. 2 – Le forme di Stato", "giorno": 1, "tipo": "flashcard", "domanda": "Stato monoclasse", "risposta": "Stato liberale in cui vota e governa solo la borghesia (suffragio ristretto)."}, {"id": "c02-f4", "capitolo": "Cap. 2 – Le forme di Stato", "giorno": 1, "tipo": "flashcard", "domanda": "Stato di polizia", "risposta": "Evoluzione settecentesca dello Stato assoluto (assolutismo illuminato): il sovrano assoluto cura il benessere dei sudditi."}, {"id": "c02-f5", "capitolo": "Cap. 2 – Le forme di Stato", "giorno": 1, "tipo": "flashcard", "domanda": "Sussidiarietà orizzontale", "risposta": "Lo Stato favorisce i privati e le formazioni sociali che svolgono attività di interesse generale (art. 118 ult. c.)."}, {"id": "c02-f6", "capitolo": "Cap. 2 – Le forme di Stato", "giorno": 1, "tipo": "flashcard", "domanda": "Regime concordatario", "risposta": "Stato e Chiesa regolano i rapporti con un accordo bilaterale (Patti Lateranensi, art. 7)."}, {"id": "c02-c1", "capitolo": "Cap. 2 – Le forme di Stato", "giorno": 1, "tipo": "crocette", "domanda": "Lo Stato liberale è definito «monoclasse» perché…", "risposta": "Il suffragio era ristretto alla borghesia.", "opzioni": ["c'era un solo partito", "votava solo una classe ristretta (la borghesia)", "esisteva una sola Camera", "il re governava da solo"], "corretta": 1}, {"id": "c02-c2", "capitolo": "Cap. 2 – Le forme di Stato", "giorno": 1, "tipo": "crocette", "domanda": "L'Italia è uno Stato…", "risposta": "È uno Stato regionale: le Regioni hanno autonomia ma non sovranità.", "opzioni": ["unitario accentrato", "federale", "regionale", "confederale"], "corretta": 2}, {"id": "c02-c3", "capitolo": "Cap. 2 – Le forme di Stato", "giorno": 1, "tipo": "crocette", "domanda": "Con quale accordo il cattolicesimo ha cessato di essere religione di Stato?", "risposta": "Con l'Accordo di Villa Madama del 1984, che ha modificato i Patti Lateranensi.", "opzioni": ["Patti Lateranensi (1929)", "Accordo di Villa Madama (1984)", "Statuto Albertino (1848)", "Trattato di Roma (1957)"], "corretta": 1}, {"id": "c03-o1", "capitolo": "Cap. 3 – Democrazia e rappresentanza", "giorno": 2, "tipo": "orale", "domanda": "Che cos'è la separazione dei poteri e come si è evoluta?", "risposta": "È il principio, formulato da **Montesquieu** nello *Spirito delle leggi* (1748), per cui il potere va diviso tra **legislativo, esecutivo e giudiziario**, così che i poteri si **controllino a vicenda** (**pesi e contrappesi**) ed evitino il dispotismo. Trova un'applicazione netta nel presidenzialismo **USA**. Nei sistemi parlamentari è più **temperata**, perché Governo e Parlamento sono legati dalla **fiducia** e dalla stessa maggioranza. Nelle democrazie pluraliste nasce poi la funzione di **indirizzo politico**, concentrata nel Governo, e una funzione di **garanzia**, affidata a **Presidente della Repubblica** e **Corte costituzionale**.", "punti_chiave": ["Montesquieu", "legislativo, esecutivo, giudiziario", "checks and balances", "indirizzo politico", "funzione di garanzia"]}, {"id": "c03-o2", "capitolo": "Cap. 3 – Democrazia e rappresentanza", "giorno": 2, "tipo": "orale", "domanda": "Che cosa significa che il parlamentare non ha vincolo di mandato?", "risposta": "Lo dice l'**art. 67**: ogni membro del Parlamento **rappresenta la Nazione** ed esercita le sue funzioni **senza vincolo di mandato**. Significa che **non è obbligato** a seguire le istruzioni degli elettori né del partito e che **non può essere revocato**. È il significato **moderno** della rappresentanza, nato con la **Rivoluzione francese**, opposto al **mandato imperativo** dei Parlamenti medievali. Il parlamentare ha però una **responsabilità politica**: gli elettori possono non rieleggerlo. Nei fatti esiste la **disciplina di partito**, che è legittima ma **non può avere conseguenze giuridiche** sul parlamentare.", "punti_chiave": ["art. 67", "rappresenta la Nazione", "divieto di mandato imperativo", "responsabilità politica", "disciplina di partito"]}, {"id": "c03-o3", "capitolo": "Cap. 3 – Democrazia e rappresentanza", "giorno": 2, "tipo": "orale", "domanda": "Che cos'è il principio di maggioranza e come si tutelano le minoranze?", "risposta": "Il principio di maggioranza ha tre significati. È un principio **funzionale**: un organo collegiale decide con il maggior numero di voti, evitando la paralisi dell'unanimità. È un principio di **rappresentanza**: serve a eleggere le assemblee. È un principio di **organizzazione politica**: una maggioranza governa e poi si sottopone al giudizio degli elettori. Le **minoranze** sono tutelate dalla **Costituzione rigida**, dalla **Corte costituzionale**, dalle **maggioranze qualificate** per le decisioni importanti, dai poteri dati a piccoli gruppi di parlamentari e dal **decentramento**, perché chi è minoranza nello Stato può governare una Regione o un Comune.", "punti_chiave": ["funzionale, di rappresentanza, di organizzazione", "Costituzione rigida", "Corte costituzionale", "maggioranze qualificate", "decentramento"]}, {"id": "c03-o4", "capitolo": "Cap. 3 – Democrazia e rappresentanza", "giorno": 2, "tipo": "orale", "domanda": "Che differenza c'è tra democrazia maggioritaria e consociativa?", "risposta": "Nella **democrazia maggioritaria** ci sono **due poli alternativi**: chi vince governa e chi perde fa **opposizione**, con **alternanza** periodica. Esempio: il Regno Unito. Funziona dove c'è un **patriottismo costituzionale**, cioè quando tutti condividono le regole e la minoranza si fida che potrà vincere la volta successiva. Nella **democrazia consociativa** i principali partiti **si accordano e condividono il potere** con dei compromessi, e non c'è una vera opposizione. È tipica di società con **fratture profonde**, religiose, linguistiche o ideologiche: Belgio, Paesi Bassi e l'Italia della Prima Repubblica.", "punti_chiave": ["alternanza", "opposizione", "patriottismo costituzionale", "compromesso e condivisione del potere", "fratture profonde"]}, {"id": "c03-o5", "capitolo": "Cap. 3 – Democrazia e rappresentanza", "giorno": 2, "tipo": "orale", "domanda": "Perché si parla di crisi della rappresentanza e quali soluzioni sono state cercate?", "risposta": "La democrazia deve far stare insieme la **governabilità**, cioè la capacità di decidere, e la **legittimazione**, cioè il consenso. Con il suffragio universale e una società complessa è difficile. Le soluzioni sono state diverse: i **partiti**, che però oggi sono in **crisi**, tanto che si parla di **scatole vuote** e di sovraccarico di domande; il **rafforzamento del Governo** e del suo capo, con il rischio della **democrazia plebiscitaria**; il **neocorporativismo**, in cui il Governo decide con sindacati e imprenditori; le **autorità indipendenti**; e per la legittimazione gli **istituti di democrazia diretta**. Una conseguenza della crisi è il **populismo**.", "punti_chiave": ["governabilità e legittimazione", "crisi dei partiti", "rafforzamento dell'esecutivo", "neocorporativismo", "democrazia diretta", "populismo"]}, {"id": "c03-o6", "capitolo": "Cap. 3 – Democrazia e rappresentanza", "giorno": 2, "tipo": "orale", "domanda": "Quali sono gli strumenti di democrazia diretta previsti dalla Costituzione?", "risposta": "Gli strumenti di democrazia diretta **affiancano e non sostituiscono** la democrazia rappresentativa. Il primo è l'**iniziativa legislativa popolare** (art. 71): **50.000 elettori** possono proporre una legge scritta in articoli. Poi c'è la **petizione** (art. 50), con cui si chiedono provvedimenti alle Camere, **senza obbligarle**. Il più importante è il **referendum**. C'è quello **abrogativo** (art. 75), che cancella una legge, si chiede con **500.000 firme** o **5 Consigli regionali** e ha il **quorum**. C'è quello **costituzionale** (art. 138), **senza quorum**. E ci sono quelli **territoriali** (artt. 132–133). Constant direbbe che è un recupero della **libertà degli antichi**.", "punti_chiave": ["affiancano e non sostituiscono", "iniziativa popolare 50.000", "petizione", "referendum abrogativo e costituzionale", "Constant"]}, {"id": "c03-f1", "capitolo": "Cap. 3 – Democrazia e rappresentanza", "giorno": 2, "tipo": "flashcard", "domanda": "Checks and balances", "risposta": "Pesi e contrappesi: i poteri dello Stato si limitano e controllano reciprocamente (Montesquieu)."}, {"id": "c03-f2", "capitolo": "Cap. 3 – Democrazia e rappresentanza", "giorno": 2, "tipo": "flashcard", "domanda": "Divieto di mandato imperativo", "risposta": "Art. 67: il parlamentare rappresenta la Nazione e non è vincolato dalle istruzioni degli elettori né del partito."}, {"id": "c03-f3", "capitolo": "Cap. 3 – Democrazia e rappresentanza", "giorno": 2, "tipo": "flashcard", "domanda": "Indirizzo politico", "risposta": "Determinazione dei fini e delle linee fondamentali della politica dello Stato, soprattutto da parte del Governo."}, {"id": "c03-f4", "capitolo": "Cap. 3 – Democrazia e rappresentanza", "giorno": 2, "tipo": "flashcard", "domanda": "Democrazia consociativa", "risposta": "Sistema in cui i principali partiti condividono il potere tramite compromessi (tipica di società divise)."}, {"id": "c03-f5", "capitolo": "Cap. 3 – Democrazia e rappresentanza", "giorno": 2, "tipo": "flashcard", "domanda": "Neocorporativismo", "risposta": "Il Governo decide le politiche economiche d'intesa con sindacati e imprenditori, affiancando il circuito rappresentativo."}, {"id": "c03-f6", "capitolo": "Cap. 3 – Democrazia e rappresentanza", "giorno": 2, "tipo": "flashcard", "domanda": "Libertà degli antichi / dei moderni", "risposta": "Constant: partecipazione diretta al potere (Atene) contro la tutela della sfera privata e la rappresentanza."}, {"id": "c03-c1", "capitolo": "Cap. 3 – Democrazia e rappresentanza", "giorno": 2, "tipo": "crocette", "domanda": "L'iniziativa legislativa popolare richiede…", "risposta": "Bastano 50.000 elettori (art. 71). Le 500.000 firme servono per il referendum.", "opzioni": ["50.000 elettori", "150.000 elettori", "500.000 elettori", "5 Consigli regionali"], "corretta": 0}, {"id": "c03-c2", "capitolo": "Cap. 3 – Democrazia e rappresentanza", "giorno": 2, "tipo": "crocette", "domanda": "Chi ha formulato la teoria della separazione dei poteri nello «Spirito delle leggi»?", "risposta": "Montesquieu, nel 1748.", "opzioni": ["Locke", "Montesquieu", "Kelsen", "Constant"], "corretta": 1}, {"id": "c03-c3", "capitolo": "Cap. 3 – Democrazia e rappresentanza", "giorno": 2, "tipo": "crocette", "domanda": "La petizione alle Camere…", "risposta": "È uno strumento di democrazia diretta senza effetti vincolanti.", "opzioni": ["obbliga il Parlamento a votare una legge", "non obbliga il Parlamento", "richiede 500.000 firme", "è un tipo di referendum"], "corretta": 1}, {"id": "c04-o1", "capitolo": "Cap. 4 – Le forme di governo", "giorno": 2, "tipo": "orale", "domanda": "Quali sono le caratteristiche della forma di governo parlamentare?", "risposta": "La forma di governo parlamentare si basa sul **rapporto di fiducia** tra Governo e Parlamento. Il Governo stabilisce l'**indirizzo politico** ed è **responsabile davanti al Parlamento**: se perde la fiducia, per esempio con una **mozione di sfiducia**, deve **dimettersi**. In Italia serve la fiducia di **entrambe le Camere**, in Germania di una sola. Il rischio principale è l'**instabilità**. Per questo nel dopoguerra si è diffusa la **razionalizzazione del parlamentarismo**, cioè regole costituzionali scritte per rendere più stabile il Governo. L'esempio più famoso è la **sfiducia costruttiva** tedesca.", "punti_chiave": ["rapporto di fiducia", "responsabilità del Governo", "instabilità", "razionalizzazione", "sfiducia costruttiva"]}, {"id": "c04-o2", "capitolo": "Cap. 4 – Le forme di governo", "giorno": 2, "tipo": "orale", "domanda": "Che cos'è la sfiducia costruttiva?", "risposta": "È l'istituto più famoso della **Costituzione tedesca del 1949**. Il Bundestag può sfiduciare il **Cancelliere** solo se **contemporaneamente elegge il suo successore** a maggioranza assoluta. Così si evitano le **crisi al buio**, cioè le crisi in cui il Governo cade senza che ci sia già un'alternativa. È un esempio di **razionalizzazione forte** del parlamentarismo. In Italia invece la sfiducia **non è costruttiva**: la nostra razionalizzazione è **debole**.", "punti_chiave": ["Germania 1949", "eleggere subito il successore", "crisi al buio", "razionalizzazione forte", "in Italia non costruttiva"]}, {"id": "c04-o3", "capitolo": "Cap. 4 – Le forme di governo", "giorno": 2, "tipo": "orale", "domanda": "Che differenza c'è tra parlamentarismo maggioritario e compromissorio?", "risposta": "Il **parlamentarismo maggioritario**, a prevalenza del Governo, si basa su un sistema **bipolare**: le elezioni producono una maggioranza chiara, il leader vincitore diventa Primo ministro con un'**investitura popolare di fatto**, e il Governo dura tutta la legislatura. L'opposizione controlla, come il **Governo ombra** inglese. Attenzione: il premier **non è eletto direttamente**. Il **parlamentarismo compromissorio**, a prevalenza del Parlamento, si basa su **molti partiti** ideologicamente distanti: il Governo nasce da **accordi dopo il voto** e la sua stabilità dipende da questi accordi. È stato il caso dell'Italia della Prima Repubblica.", "punti_chiave": ["sistema bipolare", "investitura di fatto", "Governo ombra", "multipartitismo", "coalizioni post-elettorali"]}, {"id": "c04-o4", "capitolo": "Cap. 4 – Le forme di governo", "giorno": 2, "tipo": "orale", "domanda": "Descriva la forma di governo presidenziale.", "risposta": "È tipica degli **Stati Uniti**. Il **Presidente** è sia **Capo dello Stato** sia **capo dell'esecutivo**. È eletto per **4 anni**, rieleggibile una sola volta, in modo **indiretto** tramite i grandi elettori. **Non c'è rapporto di fiducia**: il Congresso non può farlo dimettere con un voto politico, ma solo metterlo **in stato d'accusa** (**impeachment**) per reati gravi. Presidente e **Congresso** (Camera dei Rappresentanti e Senato) sono **indipendenti** ma si **controllano**: il Presidente ha il **veto** sulle leggi, il Congresso approva il bilancio e conferma alcune nomine. Non esiste un Governo collegiale, ma i **Segretari**, che riuniti formano il Gabinetto.", "punti_chiave": ["USA", "Capo dello Stato e dell'esecutivo", "niente fiducia", "impeachment", "veto"]}, {"id": "c04-o5", "capitolo": "Cap. 4 – Le forme di governo", "giorno": 2, "tipo": "orale", "domanda": "Descriva la forma di governo semipresidenziale.", "risposta": "Nel **semipresidenzialismo** il **Capo dello Stato è eletto direttamente** dal popolo ed è indipendente dal Parlamento, ma il **Governo** che nomina deve avere la **fiducia del Parlamento**. Il modello è la **Francia della V Repubblica**, dove il Presidente è eletto per 5 anni ed è **forte**: nomina il Primo ministro, presiede il Consiglio dei ministri e può indire referendum. Il rischio è la **coabitazione**, cioè un Presidente e una maggioranza di colore politico diverso. Dal **2000** il mandato presidenziale dura quanto l'Assemblea, proprio per evitarla. In Austria e Irlanda il Presidente ha solo un ruolo di **garanzia**.", "punti_chiave": ["elezione diretta", "Governo con fiducia", "Francia V Repubblica", "coabitazione", "riforma 2000"]}, {"id": "c04-o6", "capitolo": "Cap. 4 – Le forme di governo", "giorno": 2, "tipo": "orale", "domanda": "Come si è evoluto il parlamentarismo nello Stato liberale?", "risposta": "Si parte dalla **monarchia costituzionale**, come quella dello **Statuto Albertino**: il **Re** ha l'esecutivo e nomina i ministri, il **Parlamento** fa le leggi, e i due sono separati. Poi si afferma il **Governo parlamentare**. Nella prima fase, **dualista**, il Governo ha bisogno della **doppia fiducia**, del Re e del Parlamento. Nella seconda fase, **monista**, basta la fiducia **del Parlamento** e il Capo dello Stato diventa un **garante** fuori dall'indirizzo politico. Lo strumento di questo passaggio è la **controfirma** ministeriale, che sposta la responsabilità degli atti del Capo dello Stato sul Governo.", "punti_chiave": ["monarchia costituzionale", "parlamentarismo dualista", "doppia fiducia", "parlamentarismo monista", "controfirma"]}, {"id": "c04-f1", "capitolo": "Cap. 4 – Le forme di governo", "giorno": 2, "tipo": "flashcard", "domanda": "Sfiducia costruttiva", "risposta": "Germania: si può sfiduciare il Cancelliere solo eleggendo contestualmente il successore; evita le crisi al buio."}, {"id": "c04-f2", "capitolo": "Cap. 4 – Le forme di governo", "giorno": 2, "tipo": "flashcard", "domanda": "Razionalizzazione del parlamentarismo", "risposta": "Regole costituzionali scritte che disciplinano il rapporto di fiducia per rendere più stabile il Governo."}, {"id": "c04-f3", "capitolo": "Cap. 4 – Le forme di governo", "giorno": 2, "tipo": "flashcard", "domanda": "Coabitazione", "risposta": "Nel semipresidenzialismo: Presidente e maggioranza parlamentare (e premier) di schieramenti opposti."}, {"id": "c04-f4", "capitolo": "Cap. 4 – Le forme di governo", "giorno": 2, "tipo": "flashcard", "domanda": "Impeachment", "risposta": "Messa in stato d'accusa del Presidente USA da parte del Congresso per tradimento o gravi reati."}, {"id": "c04-f5", "capitolo": "Cap. 4 – Le forme di governo", "giorno": 2, "tipo": "flashcard", "domanda": "Parlamentarismo dualista", "risposta": "Il Governo deve avere la fiducia sia del Re sia del Parlamento (doppia fiducia)."}, {"id": "c04-f6", "capitolo": "Cap. 4 – Le forme di governo", "giorno": 2, "tipo": "flashcard", "domanda": "Forma direttoriale", "risposta": "Svizzera: un Consiglio federale di 7 membri, non revocabile, svolge le funzioni di Governo e di Capo dello Stato."}, {"id": "c04-c1", "capitolo": "Cap. 4 – Le forme di governo", "giorno": 2, "tipo": "crocette", "domanda": "Nella forma di governo presidenziale…", "risposta": "Non c'è rapporto di fiducia; c'è solo l'impeachment per reati gravi.", "opzioni": ["il Presidente deve avere la fiducia del Congresso", "il Congresso non può sfiduciare il Presidente", "il Presidente è eletto dal Parlamento", "il Primo ministro guida il Governo"], "corretta": 1}, {"id": "c04-c2", "capitolo": "Cap. 4 – Le forme di governo", "giorno": 2, "tipo": "crocette", "domanda": "La «coabitazione» è un fenomeno tipico…", "risposta": "Presidente e maggioranza di colore diverso: è un rischio del semipresidenzialismo.", "opzioni": ["del presidenzialismo USA", "del semipresidenzialismo francese", "della forma direttoriale svizzera", "del parlamentarismo inglese"], "corretta": 1}, {"id": "c04-c3", "capitolo": "Cap. 4 – Le forme di governo", "giorno": 2, "tipo": "crocette", "domanda": "La sfiducia costruttiva è prevista…", "risposta": "È prevista dalla Costituzione tedesca del 1949.", "opzioni": ["in Italia", "in Germania", "negli Stati Uniti", "in Francia"], "corretta": 1}, {"id": "c05-o1", "capitolo": "Cap. 5 – I sistemi elettorali", "giorno": 2, "tipo": "orale", "domanda": "Che differenza c'è tra sistema maggioritario e proporzionale?", "risposta": "Il **sistema elettorale** trasforma i voti in seggi. Nel **maggioritario** il seggio va a **chi prende più voti nel collegio**, di solito **uninominale**. Può essere a maggioranza relativa (turno unico, come nel Regno Unito) o assoluta (con **doppio turno**, come in Francia). Ha un effetto **selettivo**: premia i grandi partiti e ne **riduce il numero**, favorendo governi stabili. Nel **proporzionale** i seggi sono distribuiti **in proporzione ai voti** delle liste, spesso con una **soglia di sbarramento**. Ha un effetto **proiettivo**: fotografa la società e **moltiplica i partiti**.", "punti_chiave": ["voti in seggi", "collegio uninominale", "effetto selettivo", "effetto proiettivo", "soglia di sbarramento"]}, {"id": "c05-o2", "capitolo": "Cap. 5 – I sistemi elettorali", "giorno": 2, "tipo": "orale", "domanda": "Qual è il sistema elettorale italiano oggi e come ci siamo arrivati?", "risposta": "Fino al **1993** l'Italia usava il **proporzionale**, adatto a una società divisa ma che dava governi deboli. Dopo il **referendum del 1993** arriva il **Mattarellum**, con il **75% maggioritario**, che porta al **bipolarismo**. Nel **2005** arriva il **Porcellum**, proporzionale con **liste bloccate** e premio di maggioranza, che la Corte costituzionale ha dichiarato illegittimo con la **sentenza 1/2014**. L'**Italicum** del 2015 è stato bocciato in parte, sul **ballottaggio**, con la **sentenza 35/2017**. Oggi c'è il **Rosatellum** (2017), un sistema **misto**: circa **37% di collegi uninominali maggioritari**, circa **61% proporzionale** e 2% per l'estero. È una **legge ordinaria**.", "punti_chiave": ["Mattarellum 1993", "Porcellum e sentenza 1/2014", "Italicum e sentenza 35/2017", "Rosatellum misto", "legge ordinaria"]}, {"id": "c05-o3", "capitolo": "Cap. 5 – I sistemi elettorali", "giorno": 2, "tipo": "orale", "domanda": "Che cosa sono l'elettorato attivo e passivo? Quali sono i caratteri del voto?", "risposta": "L'**elettorato attivo** è il diritto di **votare**: spetta ai cittadini maggiorenni, oggi **18 anni sia per la Camera sia per il Senato**, dopo la riforma del 2021. L'**elettorato passivo** è il diritto di **essere eletti**: **25 anni** per la Camera e **40** per il Senato. Per l'**art. 48** il voto è **personale, eguale, libero e segreto** ed è un **dovere civico**, non giuridico, perché chi non vota non viene punito. Il diritto di voto si perde solo per **incapacità civile**, per **sentenza penale irrevocabile** o per **indegnità morale**, nei casi previsti dalla legge.", "punti_chiave": ["18 anni per votare", "25 e 40 anni per essere eletti", "personale, eguale, libero, segreto", "dovere civico", "art. 48"]}, {"id": "c05-o4", "capitolo": "Cap. 5 – I sistemi elettorali", "giorno": 2, "tipo": "orale", "domanda": "Che differenza c'è tra ineleggibilità, incompatibilità e incandidabilità?", "risposta": "L'**ineleggibilità** è un impedimento che rende **invalida l'elezione**, per esempio se si ricopre una certa carica pubblica. Si può però **rimuovere prima** del voto, lasciando la carica. L'**incompatibilità** riguarda chi è **validamente eletto** ma **non può cumulare** il seggio con un'altra carica: deve **scegliere**. L'**incandidabilità**, rafforzata dalla **legge Severino del 2012**, colpisce chi ha certe **condanne definitive** (per esempio per corruzione): **non può candidarsi**, e se la condanna arriva durante il mandato si ha la **decadenza**. Si basa sull'**indegnità morale** e **non è rimovibile**.", "punti_chiave": ["ineleggibilità rimovibile", "incompatibilità: scegliere", "incandidabilità", "legge Severino", "decadenza"]}, {"id": "c05-o5", "capitolo": "Cap. 5 – I sistemi elettorali", "giorno": 2, "tipo": "orale", "domanda": "Come si compone un sistema elettorale?", "risposta": "Un sistema elettorale ha tre componenti. La prima è il **tipo di scelta** dell'elettore: **categorica**, se sceglie una sola opzione, oppure **ordinale**, se mette in ordine i candidati. La seconda è il **collegio**: **uninominale**, se si elegge una sola persona, o **plurinominale**, se se ne eleggono più. Più è piccolo il collegio, più il sistema è selettivo. La terza è la **formula elettorale**, cioè il meccanismo che trasforma i voti in seggi: **maggioritaria** o **proporzionale**, con eventuali **soglie di sbarramento** e **premi di maggioranza**.", "punti_chiave": ["scelta categorica o ordinale", "collegio uni- o plurinominale", "formula elettorale", "sbarramento e premio"]}, {"id": "c05-o6", "capitolo": "Cap. 5 – I sistemi elettorali", "giorno": 2, "tipo": "orale", "domanda": "Come viene eletto il Presidente degli Stati Uniti?", "risposta": "L'elezione del Presidente americano è **indiretta**. I cittadini di ogni Stato votano i **grandi elettori**, che poi eleggono il Presidente. Ogni Stato ha tanti grandi elettori quanti sono i suoi **senatori e rappresentanti** al Congresso. In quasi tutti gli Stati vale il **maggioritario puro**, il **winner takes all**: chi vince nello Stato prende **tutti** i suoi grandi elettori. Fanno eccezione **Maine e Nebraska**. Il sistema è tradizionalmente **bipartitico**, con Democratici e Repubblicani.", "punti_chiave": ["elezione indiretta", "grandi elettori", "winner takes all", "Maine e Nebraska", "bipartitismo"]}, {"id": "c05-f1", "capitolo": "Cap. 5 – I sistemi elettorali", "giorno": 2, "tipo": "flashcard", "domanda": "Elettorato passivo", "risposta": "Diritto di essere eletti: 25 anni per la Camera, 40 per il Senato."}, {"id": "c05-f2", "capitolo": "Cap. 5 – I sistemi elettorali", "giorno": 2, "tipo": "flashcard", "domanda": "Soglia di sbarramento", "risposta": "Percentuale minima di voti che una lista deve ottenere per partecipare alla distribuzione dei seggi."}, {"id": "c05-f3", "capitolo": "Cap. 5 – I sistemi elettorali", "giorno": 2, "tipo": "flashcard", "domanda": "Liste bloccate", "risposta": "L'elettore non può dare preferenze: sono eletti i candidati nell'ordine deciso dal partito."}, {"id": "c05-f4", "capitolo": "Cap. 5 – I sistemi elettorali", "giorno": 2, "tipo": "flashcard", "domanda": "Rosatellum", "risposta": "Legge elettorale vigente (2017): sistema misto, circa 37% uninominale maggioritario e 61% proporzionale."}, {"id": "c05-f5", "capitolo": "Cap. 5 – I sistemi elettorali", "giorno": 2, "tipo": "flashcard", "domanda": "Incandidabilità", "risposta": "Divieto di candidarsi per chi ha condanne definitive per certi reati (legge Severino); non rimovibile."}, {"id": "c05-f6", "capitolo": "Cap. 5 – I sistemi elettorali", "giorno": 2, "tipo": "flashcard", "domanda": "Effetto selettivo / proiettivo", "risposta": "Selettivo: il maggioritario riduce il numero dei partiti. Proiettivo: il proporzionale fotografa la società."}, {"id": "c05-c1", "capitolo": "Cap. 5 – I sistemi elettorali", "giorno": 2, "tipo": "crocette", "domanda": "Quanti anni servono per votare per il Senato?", "risposta": "Dal 2021 si vota a 18 anni anche per il Senato. 40 è l'età per essere eletti senatori.", "opzioni": ["18", "21", "25", "40"], "corretta": 0}, {"id": "c05-c2", "capitolo": "Cap. 5 – I sistemi elettorali", "giorno": 2, "tipo": "crocette", "domanda": "La Corte costituzionale ha dichiarato illegittimo il «Porcellum» con la sentenza…", "risposta": "Sentenza 1/2014. La 35/2017 riguarda l'Italicum.", "opzioni": ["1/2014", "35/2017", "360/1996", "170/1984"], "corretta": 0}, {"id": "c05-c3", "capitolo": "Cap. 5 – I sistemi elettorali", "giorno": 2, "tipo": "crocette", "domanda": "La legge elettorale in Italia è…", "risposta": "È una legge ordinaria, modificabile con un'altra legge ordinaria.", "opzioni": ["una legge costituzionale", "una legge ordinaria", "un regolamento parlamentare", "un decreto del Presidente"], "corretta": 1}, {"id": "c06-o1", "capitolo": "Cap. 6 – Il Governo", "giorno": 3, "tipo": "orale", "domanda": "Come si forma il Governo in Italia?", "risposta": "Il procedimento ha diverse fasi. Prima ci sono le **consultazioni**: il Presidente della Repubblica sente i **capigruppo parlamentari**, i Presidenti delle Camere e gli ex Presidenti. A volte dà prima un **mandato esplorativo**. Poi conferisce l'**incarico**, a voce, e l'incaricato lo **accetta con riserva**. Sciolta la riserva, il Presidente **nomina il Presidente del Consiglio** e, **su sua proposta, i ministri** (art. 92). Segue il **giuramento** (art. 93). Infine, **entro 10 giorni**, il Governo si presenta alle Camere per la **fiducia** (art. 94). Da notare che consultazioni e incarico sono **prassi**: la Costituzione disciplina solo nomina, giuramento e fiducia.", "punti_chiave": ["consultazioni", "incarico con riserva", "nomina su proposta del premier", "giuramento", "fiducia entro 10 giorni"]}, {"id": "c06-o2", "capitolo": "Cap. 6 – Il Governo", "giorno": 3, "tipo": "orale", "domanda": "Che cosa prevede l'art. 94 della Costituzione?", "risposta": "L'**art. 94** regola il **rapporto di fiducia**. Il Governo deve avere la fiducia di **entrambe le Camere**. Deve presentarsi alle Camere **entro 10 giorni** dalla formazione. La fiducia si accorda o si revoca con una **mozione motivata**, votata per **appello nominale**, cioè con voto palese, così si evitano i **franchi tiratori**. La **mozione di sfiducia** deve essere firmata da almeno **1/10** dei componenti di una Camera e non può essere discussa **prima di 3 giorni**. Infine, il **voto contrario** su una proposta del Governo **non obbliga** alle dimissioni. Sono queste le regole della **debole razionalizzazione** italiana.", "punti_chiave": ["fiducia di entrambe le Camere", "10 giorni", "mozione motivata e appello nominale", "1/10 e 3 giorni", "debole razionalizzazione"]}, {"id": "c06-o3", "capitolo": "Cap. 6 – Il Governo", "giorno": 3, "tipo": "orale", "domanda": "Che cosa prevede l'art. 95 sul funzionamento del Governo?", "risposta": "L'**art. 95** combina tre principi. Il **principio monocratico**: il Presidente del Consiglio **dirige la politica generale** del Governo e ne è **responsabile**. Il **principio collegiale**: mantiene l'**unità dell'indirizzo politico e amministrativo**, **promuovendo e coordinando** l'attività dei ministri, mentre le decisioni generali le prende il **Consiglio dei ministri**. E il **principio di responsabilità**: i ministri rispondono **collegialmente** per gli atti del Consiglio dei ministri e **individualmente** per gli atti dei loro dicasteri. La **legge 400/1988** ha rafforzato il premier: convoca il Consiglio dei ministri e ne fissa l'ordine del giorno.", "punti_chiave": ["principio monocratico", "principio collegiale", "responsabilità collegiale e individuale", "legge 400/1988"]}, {"id": "c06-o4", "capitolo": "Cap. 6 – Il Governo", "giorno": 3, "tipo": "orale", "domanda": "Che cos'è la questione di fiducia?", "risposta": "Con la **questione di fiducia** il Governo lega la propria **permanenza in carica** all'approvazione di un testo, una legge o un emendamento. **Non è prevista dalla Costituzione** ma dai **regolamenti parlamentari** e dalla **legge 400/1988**. Si vota per **appello nominale**. Se la Camera **approva**, il testo passa e **decadono tutti gli emendamenti**. Se lo **respinge**, il Governo **deve dimettersi**. Va distinta dal semplice voto contrario su una proposta del Governo, che per l'art. 94 **non obbliga alle dimissioni**. Nella prassi è diventata uno strumento per **accelerare** l'approvazione delle leggi, anche dei decreti-legge da convertire.", "punti_chiave": ["non è in Costituzione", "regolamenti e legge 400/1988", "decadono gli emendamenti", "se respinta: dimissioni", "strumento di accelerazione"]}, {"id": "c06-o5", "capitolo": "Cap. 6 – Il Governo", "giorno": 3, "tipo": "orale", "domanda": "Che tipi di crisi di governo esistono e come si risolvono?", "risposta": "La crisi si apre quando il Governo **si dimette** perché è venuta meno la fiducia. È **parlamentare** quando deriva da un **voto di sfiducia** o dal rifiuto della questione di fiducia: il Governo è **obbligato** a dimettersi. È **extraparlamentare** quando il Governo si dimette **volontariamente** per una crisi nella maggioranza. È il caso più frequente in Italia, dove **nessun Governo è mai caduto per una mozione di sfiducia**. Per renderla trasparente si pratica la **parlamentarizzazione della crisi**. Il Presidente della Repubblica, dopo le **consultazioni**, può rinviare il Governo alle Camere, incaricare un nuovo premier, formare un **governo tecnico** oppure, come **extrema ratio**, sciogliere le Camere.", "punti_chiave": ["crisi parlamentare", "crisi extraparlamentare", "parlamentarizzazione", "governo tecnico", "scioglimento come extrema ratio"]}, {"id": "c06-o6", "capitolo": "Cap. 6 – Il Governo", "giorno": 3, "tipo": "orale", "domanda": "È possibile sfiduciare un singolo ministro?", "risposta": "**Sì**. Anche se l'art. 94 parla solo della fiducia al Governo intero, è ammessa la **sfiducia individuale**. Il caso storico è il **caso Mancuso** del 1995: il ministro della Giustizia del Governo tecnico Dini fu sfiduciato dal Senato, si rifiutò di dimettersi e sollevò un **conflitto di attribuzione**. La **Corte costituzionale**, con la **sentenza 7/1996**, ha riconosciuto che la sfiducia individuale è **legittima** e che il ministro sfiduciato **deve dimettersi**. Non vale invece per **sottosegretari e viceministri**, che non hanno un rapporto fiduciario diretto con il Parlamento.", "punti_chiave": ["sfiducia individuale ammessa", "caso Mancuso", "conflitto di attribuzione", "sentenza 7/1996", "non per i sottosegretari"]}, {"id": "c06-f1", "capitolo": "Cap. 6 – Il Governo", "giorno": 3, "tipo": "flashcard", "domanda": "Incarico con riserva", "risposta": "Il Presidente della Repubblica incarica a voce una persona di formare il Governo; questa scioglie la riserva quando ha lista e programma."}, {"id": "c06-f2", "capitolo": "Cap. 6 – Il Governo", "giorno": 3, "tipo": "flashcard", "domanda": "Crisi extraparlamentare", "risposta": "Dimissioni volontarie del Governo, senza un voto di sfiducia (il caso più frequente in Italia)."}, {"id": "c06-f3", "capitolo": "Cap. 6 – Il Governo", "giorno": 3, "tipo": "flashcard", "domanda": "Parlamentarizzazione della crisi", "risposta": "Il Governo dimissionario va in Parlamento a spiegare le ragioni della crisi."}, {"id": "c06-f4", "capitolo": "Cap. 6 – Il Governo", "giorno": 3, "tipo": "flashcard", "domanda": "Questione di fiducia", "risposta": "Il Governo lega la sua permanenza all'approvazione di un testo; se respinta si dimette, se approvata decadono gli emendamenti."}, {"id": "c06-f5", "capitolo": "Cap. 6 – Il Governo", "giorno": 3, "tipo": "flashcard", "domanda": "Ministro senza portafoglio", "risposta": "Ministro che non guida un ministero e svolge le funzioni delegate dal Presidente del Consiglio."}, {"id": "c06-f6", "capitolo": "Cap. 6 – Il Governo", "giorno": 3, "tipo": "flashcard", "domanda": "Governo tecnico", "risposta": "Governo guidato da figure non politiche (es. Ciampi 1993, Monti 2011); deve comunque ottenere la fiducia."}, {"id": "c06-c1", "capitolo": "Cap. 6 – Il Governo", "giorno": 3, "tipo": "crocette", "domanda": "Chi nomina i ministri?", "risposta": "Art. 92: li nomina il Presidente della Repubblica su proposta del premier.", "opzioni": ["Il Presidente del Consiglio", "Il Presidente della Repubblica, su proposta del Presidente del Consiglio", "Il Parlamento in seduta comune", "Il Consiglio dei ministri"], "corretta": 1}, {"id": "c06-c2", "capitolo": "Cap. 6 – Il Governo", "giorno": 3, "tipo": "crocette", "domanda": "Entro quanti giorni il Governo deve chiedere la fiducia alle Camere?", "risposta": "Entro 10 giorni dalla formazione (art. 94).", "opzioni": ["5", "10", "30", "60"], "corretta": 1}, {"id": "c06-c3", "capitolo": "Cap. 6 – Il Governo", "giorno": 3, "tipo": "crocette", "domanda": "La mozione di sfiducia deve essere firmata da almeno…", "risposta": "Almeno 1/10, e non può essere discussa prima di 3 giorni.", "opzioni": ["1/10 dei componenti della Camera", "1/5 dei componenti", "50 parlamentari", "la maggioranza assoluta"], "corretta": 0}, {"id": "c07-o1", "capitolo": "Cap. 7 – Il Parlamento", "giorno": 3, "tipo": "orale", "domanda": "Com'è composto il Parlamento e che cosa significa bicameralismo perfetto?", "risposta": "Il Parlamento è formato da due Camere: la **Camera dei deputati**, con **400** membri, e il **Senato della Repubblica**, con **200** membri elettivi più i **senatori a vita**, cioè gli ex Presidenti della Repubblica e fino a **5** cittadini nominati per altissimi meriti. I numeri sono stati ridotti con la **legge costituzionale 1/2020**. Si parla di **bicameralismo perfetto** o paritario perché le due Camere hanno **gli stessi poteri**: entrambe danno la **fiducia** al Governo e ogni legge deve essere approvata da entrambe **nello stesso testo**. Durano **5 anni**. La riforma del 2016, che voleva superare il bicameralismo perfetto, è stata bocciata dal referendum.", "punti_chiave": ["400 deputati e 200 senatori", "senatori a vita", "bicameralismo perfetto", "stesso testo", "legislatura di 5 anni"]}, {"id": "c07-o2", "capitolo": "Cap. 7 – Il Parlamento", "giorno": 3, "tipo": "orale", "domanda": "Quali sono le prerogative dei parlamentari?", "risposta": "Le prerogative sono garanzie che servono all'**indipendenza** del Parlamento. La prima è il **divieto di mandato imperativo** dell'**art. 67**. Poi l'**art. 68** prevede l'**insindacabilità**: il parlamentare non risponde delle **opinioni espresse e dei voti dati** nell'esercizio delle funzioni, e la garanzia vale **anche dopo la fine del mandato**. E prevede l'**inviolabilità**: senza l'**autorizzazione della Camera** di appartenenza non può essere **arrestato, perquisito, intercettato** o subire il sequestro della corrispondenza, salvo **sentenza irrevocabile** o **arresto obbligatorio in flagranza**. Dal **1993** non serve più l'autorizzazione per **iniziare un processo**.", "punti_chiave": ["art. 67", "insindacabilità", "vale anche dopo il mandato", "inviolabilità e autorizzazione", "flagranza e sentenza irrevocabile"]}, {"id": "c07-o3", "capitolo": "Cap. 7 – Il Parlamento", "giorno": 3, "tipo": "orale", "domanda": "Quali sono le funzioni del Parlamento?", "risposta": "La prima funzione è quella **legislativa** (art. 70), esercitata **collettivamente** dalle due Camere. Poi c'è la funzione di **indirizzo**, con **mozioni**, **risoluzioni** e **ordini del giorno** che orientano il Governo. C'è la funzione di **controllo**, con le **interrogazioni**, che chiedono se un fatto è vero, le **interpellanze**, che chiedono i motivi e le intenzioni del Governo, e la **sfiducia**. Ci sono le **inchieste** (art. 82), con commissioni che hanno **gli stessi poteri e limiti dell'autorità giudiziaria**. In **seduta comune** ha funzioni **elettive** e di accusa. Infine partecipa alla formazione e all'attuazione del **diritto UE**.", "punti_chiave": ["funzione legislativa", "indirizzo: mozione, risoluzione, ordine del giorno", "controllo: interrogazione e interpellanza", "inchieste (art. 82)", "seduta comune"]}, {"id": "c07-o4", "capitolo": "Cap. 7 – Il Parlamento", "giorno": 3, "tipo": "orale", "domanda": "Quando si riunisce il Parlamento in seduta comune?", "risposta": "Il Parlamento in seduta comune è formato da **tutti i deputati e senatori** riuniti ed è presieduto dal **Presidente della Camera**. Si riunisce **solo nei casi previsti dalla Costituzione**: per **eleggere il Presidente della Repubblica**, integrato dai **delegati regionali**; per riceverne il **giuramento**; per metterlo **in stato d'accusa** per alto tradimento o attentato alla Costituzione; per eleggere **5 dei 15 giudici costituzionali**; per eleggere **1/3 dei membri del CSM**; e per compilare l'elenco dei cittadini da cui si sorteggiano i giudici aggregati della Corte.", "punti_chiave": ["Presidente della Camera", "elezione e giuramento del Presidente", "stato d'accusa", "5 giudici costituzionali", "1/3 del CSM"]}, {"id": "c07-o5", "capitolo": "Cap. 7 – Il Parlamento", "giorno": 3, "tipo": "orale", "domanda": "Com'è organizzata internamente ciascuna Camera?", "risposta": "Ogni Camera ha un **Presidente**, che dirige i lavori e garantisce il regolamento, e un **Ufficio di Presidenza**. Il lavoro sulle leggi si svolge soprattutto nelle **commissioni permanenti**, una per materia, che sono un **Parlamento in miniatura**. I parlamentari si organizzano in **gruppi parlamentari**: chi non aderisce a un gruppo va nel **gruppo misto**. La **Conferenza dei capigruppo** decide programma e calendario. Le **Giunte** svolgono compiti di garanzia, come la verifica delle elezioni. Tutto è regolato dai **regolamenti parlamentari**, approvati da ciascuna Camera a **maggioranza assoluta** (art. 64), espressione della sua **autonomia**.", "punti_chiave": ["Presidente e Ufficio di Presidenza", "commissioni permanenti", "gruppi e gruppo misto", "capigruppo", "regolamenti a maggioranza assoluta"]}, {"id": "c07-o6", "capitolo": "Cap. 7 – Il Parlamento", "giorno": 3, "tipo": "orale", "domanda": "Che differenza c'è tra interrogazione, interpellanza e mozione?", "risposta": "Sono tutti strumenti del Parlamento verso il Governo. L'**interrogazione** è una **domanda** per sapere **se un fatto è vero** e se il Governo ne è informato: serve a ottenere **informazioni**. L'**interpellanza** è una domanda **scritta** sui **motivi della condotta** del Governo e sulle sue **intenzioni** future. Entrambe sono strumenti di **controllo**. La **mozione** invece è uno strumento di **indirizzo**: apre una discussione che si conclude con un **voto dell'Assemblea** che **impegna politicamente** il Governo. Anche la sfiducia è una mozione.", "punti_chiave": ["interrogazione: se un fatto è vero", "interpellanza: motivi e intenzioni", "strumenti di controllo", "mozione: indirizzo e voto"]}, {"id": "c07-f1", "capitolo": "Cap. 7 – Il Parlamento", "giorno": 3, "tipo": "flashcard", "domanda": "Bicameralismo perfetto", "risposta": "Le due Camere hanno identici poteri: entrambe danno la fiducia e approvano le leggi nello stesso testo."}, {"id": "c07-f2", "capitolo": "Cap. 7 – Il Parlamento", "giorno": 3, "tipo": "flashcard", "domanda": "Prorogatio", "risposta": "Le Camere scadute restano in carica fino alla riunione delle nuove, limitandosi agli atti indispensabili."}, {"id": "c07-f3", "capitolo": "Cap. 7 – Il Parlamento", "giorno": 3, "tipo": "flashcard", "domanda": "Insindacabilità (art. 68)", "risposta": "Il parlamentare non risponde delle opinioni e dei voti espressi nell'esercizio delle funzioni, anche dopo il mandato."}, {"id": "c07-f4", "capitolo": "Cap. 7 – Il Parlamento", "giorno": 3, "tipo": "flashcard", "domanda": "Interpellanza", "risposta": "Domanda scritta al Governo sui motivi della sua condotta e sulle sue intenzioni."}, {"id": "c07-f5", "capitolo": "Cap. 7 – Il Parlamento", "giorno": 3, "tipo": "flashcard", "domanda": "Gruppo misto", "risposta": "Gruppo in cui confluiscono i parlamentari che non aderiscono a nessun altro gruppo."}, {"id": "c07-f6", "capitolo": "Cap. 7 – Il Parlamento", "giorno": 3, "tipo": "flashcard", "domanda": "Commissione d'inchiesta (art. 82)", "risposta": "Commissione con gli stessi poteri e limiti dell'autorità giudiziaria; accerta responsabilità politiche."}, {"id": "c07-c1", "capitolo": "Cap. 7 – Il Parlamento", "giorno": 3, "tipo": "crocette", "domanda": "Quanti sono oggi i senatori elettivi?", "risposta": "Sono 200 dalla legge costituzionale 1/2020 (prima erano 315).", "opzioni": ["315", "200", "400", "630"], "corretta": 1}, {"id": "c07-c2", "capitolo": "Cap. 7 – Il Parlamento", "giorno": 3, "tipo": "crocette", "domanda": "Chi presiede il Parlamento in seduta comune?", "risposta": "Il Presidente della Camera.", "opzioni": ["Il Presidente del Senato", "Il Presidente della Repubblica", "Il Presidente della Camera", "Il deputato più anziano"], "corretta": 2}, {"id": "c07-c3", "capitolo": "Cap. 7 – Il Parlamento", "giorno": 3, "tipo": "crocette", "domanda": "I regolamenti parlamentari sono approvati…", "risposta": "Ciascuna Camera approva il proprio regolamento a maggioranza assoluta (art. 64).", "opzioni": ["a maggioranza semplice", "a maggioranza assoluta dei componenti", "con i 2/3", "con legge costituzionale"], "corretta": 1}, {"id": "c08-o1", "capitolo": "Cap. 8 – Il Presidente della Repubblica", "giorno": 4, "tipo": "orale", "domanda": "Qual è il ruolo del Presidente della Repubblica nella nostra Costituzione?", "risposta": "Il Presidente è il **Capo dello Stato** e **rappresenta l'unità nazionale** (art. 87). **Non ha nessuno dei tre poteri**, ma **partecipa a tutti** con una funzione di **garanzia e di equilibrio**. Il suo ruolo **oscilla**: nei periodi normali è un **garante** estraneo all'indirizzo politico, nelle crisi diventa più attivo, quasi un **decisore di ultima istanza** quando i partiti non trovano soluzioni. Come si è detto a lezione, è una **magistratura di influenza**: non decide direttamente, ma **influenza** e fa funzionare il sistema. È uno **sblocca-sistema** con un potere **neutro e intermediario**, e **non è un relitto storico**.", "punti_chiave": ["unità nazionale (art. 87)", "garanzia ed equilibrio", "oscillazione del ruolo", "magistratura di influenza", "sblocca-sistema"]}, {"id": "c08-o2", "capitolo": "Cap. 8 – Il Presidente della Repubblica", "giorno": 4, "tipo": "orale", "domanda": "Come viene eletto il Presidente della Repubblica?", "risposta": "È eletto dal **Parlamento in seduta comune**, integrato da **3 delegati per ogni Regione** (la Valle d'Aosta ne ha uno), scelti in modo da rappresentare anche le minoranze. Il voto è a **scrutinio segreto**. Nei **primi tre scrutini** serve la maggioranza dei **2/3** dell'assemblea, **dal quarto** basta la **maggioranza assoluta**: il quorum alto serve perché il Presidente **non sia espressione della sola maggioranza**. Può essere eletto un cittadino con **almeno 50 anni** che goda dei diritti civili e politici. Dura **7 anni**, più della legislatura. Presta **giuramento** davanti al Parlamento in seduta comune.", "punti_chiave": ["seduta comune più delegati regionali", "scrutinio segreto", "2/3 poi maggioranza assoluta", "50 anni", "7 anni"]}, {"id": "c08-o3", "capitolo": "Cap. 8 – Il Presidente della Repubblica", "giorno": 4, "tipo": "orale", "domanda": "Che cos'è la controfirma ministeriale?", "risposta": "Per l'**art. 89** **nessun atto** del Presidente della Repubblica è valido se non è **controfirmato** dai **ministri proponenti**, che **ne assumono la responsabilità**. Per gli atti con valore legislativo controfirma anche il Presidente del Consiglio. La controfirma **trasferisce la responsabilità politica** al Governo e garantisce l'**irresponsabilità** del Presidente. Il suo significato però **cambia a seconda dell'atto**. Negli atti **sostanzialmente governativi** il ministro controfirma perché la decisione è sua. In quelli **sostanzialmente presidenziali** la controfirma **certifica solo la regolarità**: è il caso della grazia, dopo la sentenza Sofri.", "punti_chiave": ["art. 89", "ministro proponente", "trasferisce la responsabilità", "irresponsabilità del Presidente", "significato diverso a seconda dell'atto"]}, {"id": "c08-o4", "capitolo": "Cap. 8 – Il Presidente della Repubblica", "giorno": 4, "tipo": "orale", "domanda": "Come si classificano gli atti del Presidente della Repubblica?", "risposta": "Si distinguono tre categorie. Gli atti **formalmente presidenziali ma sostanzialmente governativi**: decide il **Governo** e il Presidente esercita un **controllo**. Esempi: l'**emanazione** di decreti-legge, decreti legislativi e regolamenti, e l'autorizzazione a presentare i disegni di legge. Gli atti **formalmente e sostanzialmente presidenziali**: decide il **Presidente**. Esempi: la nomina dei **senatori a vita** e di **5 giudici costituzionali**, il **rinvio** delle leggi, i **messaggi**, la **grazia**. Infine gli atti **complessi o duumvirali**, decisi **insieme**: la **nomina del Presidente del Consiglio** e lo **scioglimento delle Camere**.", "punti_chiave": ["sostanzialmente governativi", "sostanzialmente presidenziali", "atti complessi o duumvirali", "nomina del premier e scioglimento"]}, {"id": "c08-o5", "capitolo": "Cap. 8 – Il Presidente della Repubblica", "giorno": 4, "tipo": "orale", "domanda": "Che cosa sono la promulgazione e il rinvio delle leggi?", "risposta": "La **promulgazione** (art. 73) è l'atto con cui il Presidente, **entro un mese**, attesta che la legge è stata approvata dalle Camere e ne **ordina la pubblicazione**. È una fase **integrativa dell'efficacia** di un atto già perfetto. Prima di promulgare può esercitare il **rinvio** (art. 74): con un **messaggio motivato** chiede alle Camere una **nuova deliberazione**, per motivi di **legittimità costituzionale** ma anche di **merito**, cioè di opportunità o di copertura finanziaria. Il rinvio si può fare **una sola volta**: se le Camere **riapprovano** la legge, il Presidente **deve promulgarla**. Quindi è un **veto sospensivo**, non la **sanzione regia** dello Statuto Albertino.", "punti_chiave": ["promulgazione entro un mese", "messaggio motivato", "legittimità e merito", "una sola volta", "veto sospensivo"]}, {"id": "c08-o6", "capitolo": "Cap. 8 – Il Presidente della Repubblica", "giorno": 4, "tipo": "orale", "domanda": "Quando e come il Presidente può sciogliere le Camere?", "risposta": "Per l'**art. 88** il Presidente può sciogliere **entrambe le Camere o una sola**, **dopo aver sentito i loro Presidenti**, il cui parere **non è vincolante**. È un atto **complesso**: la decisione è condivisa con il Governo e il Presidente del Consiglio controfirma. Si usa come **extrema ratio**, quando **non è possibile formare una maggioranza** (è lo scioglimento funzionale). C'è un limite: il **semestre bianco**. Il Presidente non può sciogliere le Camere negli **ultimi 6 mesi del suo mandato**, così non le scioglie per farsi rieleggere, **salvo** che quei mesi coincidano con gli ultimi 6 mesi della legislatura.", "punti_chiave": ["art. 88", "sentiti i Presidenti delle Camere", "atto complesso", "extrema ratio", "semestre bianco"]}, {"id": "c08-o7", "capitolo": "Cap. 8 – Il Presidente della Repubblica", "giorno": 4, "tipo": "orale", "domanda": "Che cosa dicono Kelsen e Schmitt sul custode della Costituzione?", "risposta": "È un dibattito degli **anni '30**, sulla crisi di **Weimar**. Per **Kelsen** la democrazia è una **procedura** per scegliere tra valori in conflitto e non ha bisogno di un **capo**: bisogna diffidare dell'**uomo eccezionale**, come già diceva **Platone**. Per lui il **custode della Costituzione** è un organo **giurisdizionale**, la **Corte costituzionale**. Per **Carl Schmitt** invece il custode è il **Presidente del Reich**, che con i **decreti d'emergenza** tiene unita la nazione nella crisi. La storia di Weimar, con i poteri d'emergenza usati fino all'arrivo di Hitler, ha dato ragione ai **timori di Kelsen**. La nostra Costituzione ha seguito il suo modello, con una **Corte costituzionale**.", "punti_chiave": ["Weimar", "Kelsen: la Corte come custode", "diffidare dell'uomo forte", "Schmitt: il Presidente e i decreti d'emergenza", "il modello italiano segue Kelsen"]}, {"id": "c08-o8", "capitolo": "Cap. 8 – Il Presidente della Repubblica", "giorno": 4, "tipo": "orale", "domanda": "Il Presidente della Repubblica è responsabile dei suoi atti? E la grazia?", "risposta": "Per l'**art. 90** il Presidente **non è responsabile** degli atti compiuti nell'esercizio delle funzioni, **tranne** che per **alto tradimento** e **attentato alla Costituzione**. In quei casi il **Parlamento in seduta comune** lo mette **in stato d'accusa** a **maggioranza assoluta**, e lo giudica la **Corte costituzionale integrata** da **16 cittadini** estratti a sorte. Sulla **grazia**: con il **caso Sofri** il ministro Castelli rifiutò di controfirmarla. La **Corte, con la sentenza 200/2006**, ha deciso che la grazia è un **potere proprio del Presidente**, esercitato per **ragioni umanitarie**, e che il ministro **non può rifiutare** la controfirma. Si parla di **grazia depoliticizzata**.", "punti_chiave": ["irresponsabilità (art. 90)", "alto tradimento e attentato alla Costituzione", "Corte integrata", "caso Sofri", "sentenza 200/2006"]}, {"id": "c08-f1", "capitolo": "Cap. 8 – Il Presidente della Repubblica", "giorno": 4, "tipo": "flashcard", "domanda": "Controfirma ministeriale (art. 89)", "risposta": "Firma del ministro proponente sugli atti del Presidente: il ministro se ne assume la responsabilità."}, {"id": "c08-f2", "capitolo": "Cap. 8 – Il Presidente della Repubblica", "giorno": 4, "tipo": "flashcard", "domanda": "Semestre bianco", "risposta": "Ultimi 6 mesi del mandato presidenziale: il Presidente non può sciogliere le Camere (salvo coincidenza con la fine della legislatura)."}, {"id": "c08-f3", "capitolo": "Cap. 8 – Il Presidente della Repubblica", "giorno": 4, "tipo": "flashcard", "domanda": "Atti duumvirali", "risposta": "Atti decisi insieme da Presidente e Governo: nomina del Presidente del Consiglio e scioglimento delle Camere."}, {"id": "c08-f4", "capitolo": "Cap. 8 – Il Presidente della Repubblica", "giorno": 4, "tipo": "flashcard", "domanda": "Rinvio delle leggi (art. 74)", "risposta": "Il Presidente chiede alle Camere, con messaggio motivato, di riesaminare una legge; se riapprovata, deve promulgarla."}, {"id": "c08-f5", "capitolo": "Cap. 8 – Il Presidente della Repubblica", "giorno": 4, "tipo": "flashcard", "domanda": "Magistratura di influenza", "risposta": "Definizione del Presidente: non decide direttamente ma influenza e armonizza i processi decisionali."}, {"id": "c08-f6", "capitolo": "Cap. 8 – Il Presidente della Repubblica", "giorno": 4, "tipo": "flashcard", "domanda": "Alto tradimento", "risposta": "Uno dei due reati per cui il Presidente risponde (art. 90), insieme all'attentato alla Costituzione."}, {"id": "c08-c1", "capitolo": "Cap. 8 – Il Presidente della Repubblica", "giorno": 4, "tipo": "crocette", "domanda": "Dal quarto scrutinio, per eleggere il Presidente della Repubblica serve…", "risposta": "Nei primi tre scrutini servono i 2/3, poi basta la maggioranza assoluta.", "opzioni": ["la maggioranza dei 2/3", "la maggioranza assoluta", "la maggioranza semplice", "i 3/5"], "corretta": 1}, {"id": "c08-c2", "capitolo": "Cap. 8 – Il Presidente della Repubblica", "giorno": 4, "tipo": "crocette", "domanda": "Quale atto è formalmente e sostanzialmente presidenziale?", "risposta": "La nomina dei 5 giudici costituzionali spetta al Presidente; gli altri sono governativi o complessi.", "opzioni": ["L'emanazione dei decreti-legge", "La nomina di 5 giudici costituzionali", "La nomina del Presidente del Consiglio", "L'autorizzazione a presentare i disegni di legge"], "corretta": 1}, {"id": "c08-c3", "capitolo": "Cap. 8 – Il Presidente della Repubblica", "giorno": 4, "tipo": "crocette", "domanda": "Se le Camere riapprovano una legge rinviata, il Presidente…", "risposta": "Il rinvio si può fare una sola volta: poi la legge va promulgata.", "opzioni": ["può rinviarla di nuovo", "deve promulgarla", "può rivolgersi alla Corte costituzionale", "può sciogliere le Camere"], "corretta": 1}, {"id": "c09-o1", "capitolo": "Cap. 9 – La Corte costituzionale", "giorno": 4, "tipo": "orale", "domanda": "Com'è composta la Corte costituzionale?", "risposta": "La Corte è composta da **15 giudici**: **5 nominati dal Presidente della Repubblica**, **5 eletti dal Parlamento in seduta comune** con maggioranze qualificate, e **5 dalle supreme magistrature**, cioè **3 dalla Cassazione**, **1 dal Consiglio di Stato** e **1 dalla Corte dei conti** (art. 135). Si scelgono tra **magistrati** delle giurisdizioni superiori, **professori ordinari** di diritto e **avvocati con almeno 20 anni** di professione. Durano **9 anni** e **non sono rieleggibili**. Il **Presidente** della Corte è eletto dai giudici e dura 3 anni. La composizione mescola nomine **politiche** e **tecniche**. Come si è detto a lezione, la Corte può funzionare con **almeno 11 giudici**.", "punti_chiave": ["15 giudici", "5 Presidente, 5 Parlamento, 5 magistrature", "requisiti", "9 anni non rinnovabili", "almeno 11 giudici"]}, {"id": "c09-o2", "capitolo": "Cap. 9 – La Corte costituzionale", "giorno": 4, "tipo": "orale", "domanda": "Quali sono le competenze della Corte costituzionale?", "risposta": "Secondo l'**art. 134** la Corte giudica sulla **legittimità costituzionale delle leggi e degli atti con forza di legge** dello Stato e delle Regioni. Risolve i **conflitti di attribuzione tra i poteri dello Stato** e quelli **tra Stato e Regioni** e tra Regioni. Giudica le **accuse contro il Presidente della Repubblica**. In più, per legge costituzionale, decide sull'**ammissibilità del referendum abrogativo**. **Non** giudica invece i **regolamenti** e le altre fonti secondarie, che sono di competenza del giudice amministrativo.", "punti_chiave": ["art. 134", "legittimità delle leggi", "conflitti di attribuzione", "accuse al Presidente", "ammissibilità del referendum"]}, {"id": "c09-o3", "capitolo": "Cap. 9 – La Corte costituzionale", "giorno": 4, "tipo": "orale", "domanda": "Come si arriva alla Corte costituzionale in via incidentale?", "risposta": "È la via **più importante**. La questione nasce **durante un processo**, il **giudizio a quo**: il **giudice**, d'ufficio o su richiesta di una parte, dubita della costituzionalità di una legge che deve applicare. Prima deve verificare due requisiti. La **rilevanza**: la legge deve servire **per decidere quel processo**. E la **non manifesta infondatezza**: deve avere un **dubbio serio**, senza bisogno di essere certo. Poi emette un'**ordinanza di rimessione** motivata, che **sospende il processo** e porta la questione alla Corte. Il cittadino quindi **non può ricorrere direttamente**: il nostro modello è **accentrato, successivo e indiretto**.", "punti_chiave": ["giudizio a quo", "rilevanza", "non manifesta infondatezza", "ordinanza di rimessione", "modello accentrato e indiretto"]}, {"id": "c09-o4", "capitolo": "Cap. 9 – La Corte costituzionale", "giorno": 4, "tipo": "orale", "domanda": "Che differenza c'è tra giudizio in via incidentale e in via principale?", "risposta": "Nel giudizio in **via incidentale** la questione **nasce in un processo** e la solleva un **giudice**, dopo aver verificato **rilevanza** e **non manifesta infondatezza**. È un giudizio **concreto**. Nel giudizio in **via principale** c'è un **ricorso diretto** alla Corte, **senza un processo**: lo propone lo **Stato contro una legge regionale** oppure una **Regione contro una legge statale** o di un'altra Regione, **entro 60 giorni** dalla pubblicazione (art. 127). Lo Stato può far valere **qualsiasi vizio**, la Regione solo la **lesione delle sue competenze**. È un giudizio **astratto**.", "punti_chiave": ["incidentale: nasce in un processo", "principale: ricorso diretto", "Stato contro Regione", "60 giorni", "concreto e astratto"]}, {"id": "c09-o5", "capitolo": "Cap. 9 – La Corte costituzionale", "giorno": 4, "tipo": "orale", "domanda": "Che tipi di sentenze può emettere la Corte?", "risposta": "Con l'**inammissibilità** la Corte non entra nel merito perché manca un presupposto, per esempio la rilevanza. Con il **rigetto** dichiara la questione **infondata**: la legge **resta in vigore** e l'effetto vale **solo per quel giudizio**, quindi altri giudici possono riproporre la questione. L'**interpretativa di rigetto** dice che la legge è costituzionale **se interpretata in un certo modo**. Con l'**accoglimento** la Corte dichiara l'**illegittimità**: l'effetto è **erga omnes** e la norma **non si applica più dal giorno successivo alla pubblicazione** (art. 136), anche ai rapporti ancora pendenti. Ci sono poi le sentenze **manipolative**, **additive** e **sostitutive**. Le decisioni **non sono impugnabili**.", "punti_chiave": ["inammissibilità", "rigetto inter partes", "interpretativa di rigetto", "accoglimento erga omnes (art. 136)", "additive e sostitutive"]}, {"id": "c09-o6", "capitolo": "Cap. 9 – La Corte costituzionale", "giorno": 4, "tipo": "orale", "domanda": "Che cosa sono i conflitti di attribuzione?", "risposta": "Sono controversie su **chi ha la competenza** a fare qualcosa. I conflitti **tra poteri dello Stato** nascono quando un potere lamenta che un altro gli ha **usurpato** una competenza o ne ha **ostacolato** l'esercizio (è l'**interferenza**). Esempi famosi sono il **caso Mancuso** (sfiducia individuale) e il **caso Sofri** (grazia). C'è prima una fase di **ammissibilità** e poi la decisione su **a chi spetta** il potere. I conflitti **tra Stato e Regioni** riguardano **atti**, amministrativi o giurisdizionali, che invadono le competenze dell'altro ente. Attenzione: se invece si contesta una **legge**, si usa il **giudizio in via principale**.", "punti_chiave": ["usurpazione e interferenza", "poteri dello Stato", "casi Mancuso e Sofri", "Stato e Regioni", "atti e non leggi"]}, {"id": "c09-o7", "capitolo": "Cap. 9 – La Corte costituzionale", "giorno": 4, "tipo": "orale", "domanda": "Che cos'è la giustizia costituzionale e quali modelli esistono?", "risposta": "La **giustizia costituzionale** è il **controllo giurisdizionale del rispetto della Costituzione**: è la garanzia della **rigidità costituzionale** e difende le minoranze dalla **tirannia della maggioranza**. Ci sono due modelli principali. Il modello **diffuso**, nato negli **USA** con **Marbury v. Madison (1803)**: ogni giudice può non applicare una legge incostituzionale. E il modello **accentrato**, ideato da **Kelsen**: solo una Corte decide. L'Italia ha un modello **accentrato, successivo e indiretto**. Il controllo **preventivo** è rimasto solo per gli Statuti regionali. Per Kelsen l'attività della Corte è **giurisdizionale**, per altri ha anche una natura **politica**, perché limita il Parlamento.", "punti_chiave": ["garanzia della rigidità", "modello diffuso: Marbury v. Madison", "modello accentrato: Kelsen", "successivo e indiretto", "natura giurisdizionale o politica"]}, {"id": "c09-f1", "capitolo": "Cap. 9 – La Corte costituzionale", "giorno": 4, "tipo": "flashcard", "domanda": "Rilevanza", "risposta": "Requisito del giudizio incidentale: la legge dubbia deve servire per decidere il processo in corso."}, {"id": "c09-f2", "capitolo": "Cap. 9 – La Corte costituzionale", "giorno": 4, "tipo": "flashcard", "domanda": "Non manifesta infondatezza", "risposta": "Requisito del giudizio incidentale: il giudice deve avere un dubbio serio (non la certezza) di incostituzionalità."}, {"id": "c09-f3", "capitolo": "Cap. 9 – La Corte costituzionale", "giorno": 4, "tipo": "flashcard", "domanda": "Sentenza additiva", "risposta": "La Corte dichiara illegittima una norma «nella parte in cui non prevede» qualcosa, aggiungendo la regola mancante."}, {"id": "c09-f4", "capitolo": "Cap. 9 – La Corte costituzionale", "giorno": 4, "tipo": "flashcard", "domanda": "Efficacia erga omnes", "risposta": "La sentenza di accoglimento vale per tutti: la norma non si applica più dal giorno dopo la pubblicazione (art. 136)."}, {"id": "c09-f5", "capitolo": "Cap. 9 – La Corte costituzionale", "giorno": 4, "tipo": "flashcard", "domanda": "Marbury v. Madison", "risposta": "Sentenza USA del 1803: nasce il controllo di costituzionalità delle leggi (modello diffuso)."}, {"id": "c09-f6", "capitolo": "Cap. 9 – La Corte costituzionale", "giorno": 4, "tipo": "flashcard", "domanda": "Dissenting opinion", "risposta": "Opinione dissenziente resa pubblica da un giudice; non esiste nella Corte costituzionale italiana."}, {"id": "c09-c1", "capitolo": "Cap. 9 – La Corte costituzionale", "giorno": 4, "tipo": "crocette", "domanda": "Quanti giudici costituzionali elegge il Parlamento in seduta comune?", "risposta": "5 su 15. Gli altri 5 li nomina il Presidente e 5 le supreme magistrature.", "opzioni": ["3", "5", "10", "15"], "corretta": 1}, {"id": "c09-c2", "capitolo": "Cap. 9 – La Corte costituzionale", "giorno": 4, "tipo": "crocette", "domanda": "Con una sentenza di rigetto la Corte…", "risposta": "Il rigetto vale per quel giudizio; altri giudici possono risollevare la questione.", "opzioni": ["dichiara la legge costituzionale per sempre", "respinge quella questione e la legge resta in vigore", "abroga la legge", "annulla la legge"], "corretta": 1}, {"id": "c09-c3", "capitolo": "Cap. 9 – La Corte costituzionale", "giorno": 4, "tipo": "crocette", "domanda": "La Corte costituzionale NON giudica…", "risposta": "I regolamenti sono fonti secondarie: li giudica il giudice amministrativo.", "opzioni": ["i decreti-legge", "le leggi regionali", "i regolamenti del Governo", "i decreti legislativi"], "corretta": 2}, {"id": "c10-o1", "capitolo": "Cap. 10 – La Costituzione", "giorno": 5, "tipo": "orale", "domanda": "Che differenza c'è tra Costituzione flessibile e rigida?", "risposta": "Una Costituzione è **flessibile** quando si può modificare con una **legge ordinaria**: se una legge la contraddice, **prevale la legge**. Sono tipiche dell'**Ottocento**, spesso **concesse** dal sovrano e **brevi**, come lo **Statuto Albertino** del 1848. Proprio la flessibilità ha permesso al **fascismo** di affermarsi in modo legale. È **rigida** quando per modificarla serve un **procedimento aggravato** e quando un **giudice**, la Corte costituzionale, garantisce che **prevalga sulla legge**. Sono tipiche del **Novecento** e sono **lunghe**. La rigidità serve a impedire che la **maggioranza** cambi da sola le regole del gioco. La nostra Costituzione è **rigida** (art. 138).", "punti_chiave": ["flessibile: legge ordinaria", "Statuto Albertino", "rigida: procedimento aggravato", "garanzia della Corte", "art. 138"]}, {"id": "c10-o2", "capitolo": "Cap. 10 – La Costituzione", "giorno": 5, "tipo": "orale", "domanda": "Come è nata la Costituzione italiana?", "risposta": "Dopo la caduta del fascismo nel **1943**, il **CLN** chiede un processo costituente. Con il **patto di Salerno (1944)** si decide di eleggere un'**Assemblea costituente** e di rinviare la scelta tra monarchia e repubblica. Il **2 giugno 1946** si svolge il **referendum istituzionale**, vinto dalla **Repubblica**, e insieme si elegge la **Costituente**, con 556 membri e **il primo voto delle donne**. Il progetto lo prepara la **Commissione dei 75**. La Costituzione è approvata il **22 dicembre 1947** con circa il **90%** dei voti ed entra in vigore il **1° gennaio 1948**. Il largo consenso spiega perché è **lunga** e **compromissoria**.", "punti_chiave": ["CLN", "2 giugno 1946", "Assemblea costituente", "Commissione dei 75", "1° gennaio 1948", "lunga e compromissoria"]}, {"id": "c10-o3", "capitolo": "Cap. 10 – La Costituzione", "giorno": 5, "tipo": "orale", "domanda": "Quali sono i caratteri e la struttura della Costituzione italiana?", "risposta": "La Costituzione italiana è **rigida**, **scritta**, **lunga**, **votata** e non concessa, **democratica**, **compromissoria** e **programmatica**, perché indica obiettivi al legislatore. È divisa in quattro parti: i **Principi fondamentali** (artt. 1–12), la **Parte prima sui diritti e doveri** dei cittadini (artt. 13–54), la **Parte seconda sull'ordinamento della Repubblica** (artt. 55–139) e le **18 disposizioni transitorie e finali**, tra cui la XII, che vieta di ricostituire il **partito fascista**. Secondo il prof è **aperta**: non dice quale valore prevale, ma **quali non si possono sacrificare**.", "punti_chiave": ["rigida, scritta, lunga, votata", "programmatica", "principi fondamentali 1–12", "Parte I e II", "disposizioni transitorie"]}, {"id": "c10-o4", "capitolo": "Cap. 10 – La Costituzione", "giorno": 5, "tipo": "orale", "domanda": "Come si modifica la Costituzione?", "risposta": "Con il **procedimento aggravato dell'art. 138**. Ogni Camera approva la legge **due volte**, con un intervallo di **almeno 3 mesi**. Nella **seconda votazione** serve almeno la **maggioranza assoluta**. Se la legge ottiene i **2/3** in entrambe le Camere, è promulgata **senza referendum**. Se ottiene solo la maggioranza assoluta, **entro 3 mesi** dalla pubblicazione si può chiedere un **referendum costituzionale**: lo possono chiedere **1/5 dei membri di una Camera**, **500.000 elettori** o **5 Consigli regionali**. Il referendum **non ha quorum**: decide la maggioranza dei voti validi. Così si usano le leggi di **revisione** e le altre **leggi costituzionali**.", "punti_chiave": ["doppia deliberazione", "3 mesi", "maggioranza assoluta", "2/3 e niente referendum", "referendum senza quorum"]}, {"id": "c10-o5", "capitolo": "Cap. 10 – La Costituzione", "giorno": 5, "tipo": "orale", "domanda": "Ci sono limiti alla revisione costituzionale?", "risposta": "Sì. Il **limite esplicito** è l'**art. 139**: *la forma repubblicana non può essere oggetto di revisione costituzionale*. Deriva dalla scelta del **referendum del 1946** e oggi si interpreta in modo ampio, come tutela della **democrazia** e della **sovranità popolare**. Poi ci sono i **limiti impliciti**, cioè i **principi supremi** dell'ordinamento: i **diritti inviolabili** (art. 2), l'**unità e indivisibilità della Repubblica** (art. 5) e in generale i valori dei primi 12 articoli. La **Corte costituzionale (sentenza 1146/1988)** ha affermato di poter giudicare **anche le leggi costituzionali** che violano questi principi.", "punti_chiave": ["art. 139 forma repubblicana", "limiti impliciti", "principi supremi", "diritti inviolabili", "sentenza 1146/1988"]}, {"id": "c10-o6", "capitolo": "Cap. 10 – La Costituzione", "giorno": 5, "tipo": "orale", "domanda": "Che differenza c'è tra potere costituente e potere costituito?", "risposta": "Il **potere costituente** è il potere di **creare una nuova Costituzione** e di fondare un nuovo ordinamento: in Italia lo ha esercitato l'**Assemblea costituente**. È in teoria un potere **libero nel fine**, ma anche la Costituente aveva un limite, il risultato del **referendum del 1946** per la **Repubblica**. Il **potere costituito** è quello degli organi che **nascono dalla Costituzione** e devono **rispettarla**. Anche il potere di **revisione** dell'art. 138 è un potere **costituito**, e per questo ha dei limiti come l'art. 139. Il nuovo ordinamento ha bisogno anche di un **consenso esterno**, il **riconoscimento** degli altri Stati, ma lo Stato **si legittima da sé**.", "punti_chiave": ["creare una nuova Costituzione", "Assemblea costituente", "potere costituito", "la revisione è potere costituito", "riconoscimento internazionale"]}, {"id": "c10-f1", "capitolo": "Cap. 10 – La Costituzione", "giorno": 5, "tipo": "flashcard", "domanda": "Costituzione rigida", "risposta": "Costituzione modificabile solo con un procedimento aggravato e garantita da un giudice delle leggi."}, {"id": "c10-f2", "capitolo": "Cap. 10 – La Costituzione", "giorno": 5, "tipo": "flashcard", "domanda": "Costituzione ottriata", "risposta": "Costituzione concessa dal sovrano (es. Statuto Albertino), tipicamente flessibile e breve."}, {"id": "c10-f3", "capitolo": "Cap. 10 – La Costituzione", "giorno": 5, "tipo": "flashcard", "domanda": "Art. 139", "risposta": "«La forma repubblicana non può essere oggetto di revisione costituzionale»: limite esplicito alla revisione."}, {"id": "c10-f4", "capitolo": "Cap. 10 – La Costituzione", "giorno": 5, "tipo": "flashcard", "domanda": "Principi supremi", "risposta": "Limiti impliciti alla revisione: diritti inviolabili, unità della Repubblica, valori dei primi 12 articoli."}, {"id": "c10-f5", "capitolo": "Cap. 10 – La Costituzione", "giorno": 5, "tipo": "flashcard", "domanda": "Potere costituente", "risposta": "Potere di creare una nuova Costituzione (l'Assemblea costituente del 1946–47)."}, {"id": "c10-f6", "capitolo": "Cap. 10 – La Costituzione", "giorno": 5, "tipo": "flashcard", "domanda": "Commissione dei 75", "risposta": "Commissione dell'Assemblea costituente che redasse il progetto di Costituzione."}, {"id": "c10-c1", "capitolo": "Cap. 10 – La Costituzione", "giorno": 5, "tipo": "crocette", "domanda": "Nel referendum costituzionale (art. 138)…", "risposta": "Il referendum costituzionale non ha quorum; quello abrogativo sì.", "opzioni": ["serve il quorum del 50%+1 degli aventi diritto", "non è previsto un quorum", "votano solo i parlamentari", "serve la maggioranza dei 2/3"], "corretta": 1}, {"id": "c10-c2", "capitolo": "Cap. 10 – La Costituzione", "giorno": 5, "tipo": "crocette", "domanda": "Il referendum costituzionale NON si può chiedere se la legge è stata approvata…", "risposta": "Con i 2/3 in seconda votazione niente referendum.", "opzioni": ["a maggioranza assoluta", "con i 2/3 nella seconda votazione di entrambe le Camere", "dal Senato", "entro 3 mesi"], "corretta": 1}, {"id": "c10-c3", "capitolo": "Cap. 10 – La Costituzione", "giorno": 5, "tipo": "crocette", "domanda": "La Costituzione italiana è entrata in vigore il…", "risposta": "Approvata il 22/12/1947, in vigore dal 1° gennaio 1948.", "opzioni": ["2 giugno 1946", "22 dicembre 1947", "1° gennaio 1948", "1° gennaio 1956"], "corretta": 2}, {"id": "c11-o1", "capitolo": "Cap. 11 – Le fonti del diritto", "giorno": 5, "tipo": "orale", "domanda": "Che cosa sono le fonti del diritto e come si classificano?", "risposta": "Le **fonti del diritto** sono gli **atti o fatti** che l'ordinamento abilita a **produrre norme giuridiche**. Si distinguono le fonti di **produzione**, che **creano** le norme, e le fonti di **cognizione**, che permettono di **conoscerle**, come la **Gazzetta Ufficiale**. Le fonti di produzione possono essere **fonti-atto**, cioè atti **volontari** di un soggetto abilitato come la legge, o **fonti-fatto**, cioè comportamenti a cui l'ordinamento riconosce valore, come la **consuetudine**. Va distinta anche la **disposizione**, che è il **testo**, dalla **norma**, che è il **significato** ricavato con l'interpretazione.", "punti_chiave": ["atti o fatti che producono norme", "produzione e cognizione", "fonti-atto e fonti-fatto", "consuetudine", "disposizione e norma"]}, {"id": "c11-o2", "capitolo": "Cap. 11 – Le fonti del diritto", "giorno": 5, "tipo": "orale", "domanda": "Qual è la gerarchia delle fonti nell'ordinamento italiano?", "risposta": "Al vertice ci sono la **Costituzione e le leggi costituzionali**. Le **fonti dell'UE** hanno una posizione particolare: se direttamente efficaci **prevalgono** sulle leggi interne, salvo i **controlimiti**. Poi vengono le **fonti primarie**: le **leggi ordinarie** statali e **regionali**, gli **atti con forza di legge**, cioè **decreti-legge** e **decreti legislativi**, e i **regolamenti parlamentari**. I **trattati internazionali** fanno da **norme interposte** (art. 117). Sotto ci sono le **fonti secondarie**, cioè i **regolamenti** del Governo, dei ministri, delle Regioni e degli enti locali. All'ultimo gradino ci sono le **consuetudini**, che non possono andare contro le fonti superiori.", "punti_chiave": ["Costituzione al vertice", "fonti UE", "fonti primarie", "atti con forza di legge", "regolamenti", "consuetudini"]}, {"id": "c11-o3", "capitolo": "Cap. 11 – Le fonti del diritto", "giorno": 5, "tipo": "orale", "domanda": "Come si risolvono le antinomie tra norme?", "risposta": "Un'**antinomia** è un contrasto tra due norme che regolano lo stesso caso. Prima si prova con l'**interpretazione**, poi si usano **quattro criteri**. Il **cronologico**, *lex posterior*: tra norme dello stesso livello prevale la **più recente**, con l'**abrogazione**, che vale per il futuro. Il **gerarchico**, *lex superior*: prevale la norma **di grado superiore**, con l'**annullamento**, che vale anche per il passato tranne i rapporti esauriti. Quello di **specialità**, *lex specialis*: la norma **speciale** deroga a quella generale, ma entrambe restano valide. E quello di **competenza**: prevale la fonte **competente** sulla materia, per esempio legge statale contro legge regionale.", "punti_chiave": ["cronologico e abrogazione", "gerarchico e annullamento", "specialità e deroga", "competenza", "ex nunc ed ex tunc"]}, {"id": "c11-o4", "capitolo": "Cap. 11 – Le fonti del diritto", "giorno": 5, "tipo": "orale", "domanda": "Mi descriva il procedimento legislativo ordinario.", "risposta": "Si parte dall'**iniziativa** (art. 71), che spetta ai **parlamentari**, al **Governo**, a **50.000 elettori**, ai **Consigli regionali** e al **CNEL**. Il progetto va alla **commissione** competente, in sede **referente** (la commissione prepara e l'Aula decide), **redigente** (la commissione approva gli articoli e l'Aula fa il voto finale) o **deliberante** (fa tutto la commissione). Alcune leggi hanno la **riserva di Assemblea**: costituzionali, elettorali, di delega, di ratifica e di bilancio. In Aula ci sono tre fasi: discussione generale, voto degli articoli e voto finale. Poi passa all'altra Camera, con la **navetta**, finché il testo non è **identico**. Seguono la **promulgazione** del Presidente entro un mese e la **pubblicazione** in Gazzetta, con la **vacatio legis** di 15 giorni.", "punti_chiave": ["iniziativa (art. 71)", "referente, redigente, deliberante", "riserva di Assemblea", "navetta", "promulgazione e pubblicazione", "vacatio legis"]}, {"id": "c11-o5", "capitolo": "Cap. 11 – Le fonti del diritto", "giorno": 5, "tipo": "orale", "domanda": "Che differenza c'è tra decreto-legge e decreto legislativo?", "risposta": "Sono entrambi **atti del Governo con forza di legge**. Il **decreto-legge** (art. 77) il Governo lo adotta **da solo**, sotto la sua responsabilità, **in casi straordinari di necessità e urgenza**. Entra in vigore **subito**, ma deve essere **convertito in legge** dal Parlamento **entro 60 giorni**, altrimenti **decade fin dall'inizio** (salvo una **legge di sanatoria**). Il **decreto legislativo** (art. 76) invece il Governo lo adotta **su delega** del Parlamento, che con una **legge delega** fissa **principi e criteri direttivi**, **tempo** e **oggetto**. **Non va convertito**, ma se il Governo supera i limiti c'è l'**eccesso di delega**. In sintesi: nel decreto-legge il Parlamento interviene **dopo**, nel decreto legislativo **prima**.", "punti_chiave": ["necessità e urgenza", "conversione in 60 giorni", "decadenza ex tunc", "legge delega: principi, tempo, oggetto", "eccesso di delega"]}, {"id": "c11-o6", "capitolo": "Cap. 11 – Le fonti del diritto", "giorno": 5, "tipo": "orale", "domanda": "Quali abusi ci sono stati nell'uso del decreto-legge?", "risposta": "Il primo è la **reiterazione**: alla scadenza dei 60 giorni il Governo riproponeva un decreto identico, creando **catene di decreti**. La **Corte costituzionale l'ha dichiarata illegittima con la sentenza 360/1996**, perché contraddice la **provvisorietà** e la **straordinarietà** del decreto. Il secondo è l'**eterogeneità**: decreti con dentro materie diverse. Con le **sentenze 22/2012 e 32/2014** la Corte ha detto che il decreto deve essere **omogeneo** e restarlo anche **in sede di conversione**: il Parlamento non può aggiungere emendamenti estranei. Anche **Napolitano** ha richiamato più volte le Camere. Secondo il prof l'effetto è stato **paradossale**: si è limitato più il **Parlamento** che il Governo.", "punti_chiave": ["reiterazione", "sentenza 360/1996", "omogeneità", "sentenze 22/2012 e 32/2014", "effetto paradossale"]}, {"id": "c11-o7", "capitolo": "Cap. 11 – Le fonti del diritto", "giorno": 5, "tipo": "orale", "domanda": "Che cos'è la riserva di legge e di quali tipi è?", "risposta": "La **riserva di legge** è un principio di **garanzia**: in certe materie, soprattutto quelle che riguardano i **diritti**, la disciplina deve venire dal **Parlamento**, che rappresenta i cittadini, e non dal solo esecutivo. È **assoluta** quando la materia va regolata **tutta dalla legge**, senza regolamenti: è il caso della libertà personale (art. 13). È **relativa** quando la legge fissa i **principi** e il regolamento i dettagli: è il caso dell'organizzazione della PA (art. 97) e delle tasse (art. 23). È **rinforzata** quando la Costituzione pone **vincoli di contenuto** (art. 16: solo per **sanità o sicurezza**) o **di procedimento**. È **formale** quando serve proprio una **legge del Parlamento** e non basta un decreto del Governo. Spesso si accompagna alla **riserva di giurisdizione**.", "punti_chiave": ["garanzia", "assoluta", "relativa", "rinforzata per contenuto o procedimento", "formale", "riserva di giurisdizione"]}, {"id": "c11-o8", "capitolo": "Cap. 11 – Le fonti del diritto", "giorno": 5, "tipo": "orale", "domanda": "Che cos'è il referendum abrogativo?", "risposta": "È lo strumento di **democrazia diretta** previsto dall'**art. 75**. Serve a **cancellare**, in tutto o in parte, una **legge** o un **atto con forza di legge**: è una **legislazione negativa** e non può introdurre norme nuove. Lo chiedono **500.000 elettori** o **5 Consigli regionali**. La **Cassazione** controlla la **regolarità** delle firme, la **Corte costituzionale** l'**ammissibilità**. Sono escluse le leggi **tributarie e di bilancio**, di **amnistia e indulto** e di **autorizzazione alla ratifica dei trattati**, più i limiti impliciti fissati dalla Corte. Per essere valido deve votare **la maggioranza degli aventi diritto** (è il **quorum**).", "punti_chiave": ["art. 75", "legislazione negativa", "500.000 elettori o 5 Consigli", "Cassazione e Corte costituzionale", "materie escluse", "quorum"]}, {"id": "c11-f1", "capitolo": "Cap. 11 – Le fonti del diritto", "giorno": 5, "tipo": "flashcard", "domanda": "Fonti di cognizione", "risposta": "Strumenti per conoscere le norme, come la Gazzetta Ufficiale."}, {"id": "c11-f2", "capitolo": "Cap. 11 – Le fonti del diritto", "giorno": 5, "tipo": "flashcard", "domanda": "Consuetudine", "risposta": "Fonte-fatto: comportamento ripetuto (diuturnitas) accompagnato dalla convinzione della sua obbligatorietà (opinio iuris)."}, {"id": "c11-f3", "capitolo": "Cap. 11 – Le fonti del diritto", "giorno": 5, "tipo": "flashcard", "domanda": "Abrogazione", "risposta": "Cessazione dell'efficacia di una norma per effetto di una norma successiva (criterio cronologico); espressa, tacita o implicita."}, {"id": "c11-f4", "capitolo": "Cap. 11 – Le fonti del diritto", "giorno": 5, "tipo": "flashcard", "domanda": "Decreto-legge (art. 77)", "risposta": "Atto con forza di legge del Governo in casi straordinari di necessità e urgenza; va convertito entro 60 giorni."}, {"id": "c11-f5", "capitolo": "Cap. 11 – Le fonti del diritto", "giorno": 5, "tipo": "flashcard", "domanda": "Decreto legislativo (art. 76)", "risposta": "Atto con forza di legge del Governo su delega del Parlamento (principi e criteri direttivi, tempo, oggetto)."}, {"id": "c11-f6", "capitolo": "Cap. 11 – Le fonti del diritto", "giorno": 5, "tipo": "flashcard", "domanda": "Delegificazione", "risposta": "Una legge autorizza un regolamento a disciplinare una materia e abroga le leggi precedenti dall'entrata in vigore del regolamento."}, {"id": "c11-f7", "capitolo": "Cap. 11 – Le fonti del diritto", "giorno": 5, "tipo": "flashcard", "domanda": "Vacatio legis", "risposta": "Periodo (di regola 15 giorni) tra la pubblicazione e l'entrata in vigore di una legge."}, {"id": "c11-f8", "capitolo": "Cap. 11 – Le fonti del diritto", "giorno": 5, "tipo": "flashcard", "domanda": "Riserva di legge assoluta", "risposta": "La materia deve essere disciplinata interamente dalla legge, senza spazio per i regolamenti (es. art. 13)."}, {"id": "c11-c1", "capitolo": "Cap. 11 – Le fonti del diritto", "giorno": 5, "tipo": "crocette", "domanda": "Il decreto-legge non convertito entro 60 giorni…", "risposta": "Decade ex tunc, salvo legge di sanatoria.", "opzioni": ["resta in vigore come regolamento", "perde efficacia fin dall'inizio", "diventa automaticamente legge", "perde efficacia solo per il futuro"], "corretta": 1}, {"id": "c11-c2", "capitolo": "Cap. 11 – Le fonti del diritto", "giorno": 5, "tipo": "crocette", "domanda": "Quale fonte NON è primaria?", "risposta": "Il regolamento governativo è una fonte secondaria.", "opzioni": ["Decreto legislativo", "Legge regionale", "Regolamento governativo", "Regolamento parlamentare"], "corretta": 2}, {"id": "c11-c3", "capitolo": "Cap. 11 – Le fonti del diritto", "giorno": 5, "tipo": "crocette", "domanda": "Il criterio che risolve il contrasto tra legge statale e legge regionale è…", "risposta": "Sono fonti dello stesso livello con ambiti diversi: si usa il criterio di competenza.", "opzioni": ["cronologico", "gerarchico", "di competenza", "di specialità"], "corretta": 2}, {"id": "c11-c4", "capitolo": "Cap. 11 – Le fonti del diritto", "giorno": 5, "tipo": "crocette", "domanda": "Quale legge NON può essere sottoposta a referendum abrogativo?", "risposta": "L'art. 75 esclude le leggi tributarie e di bilancio, di amnistia e indulto e di ratifica dei trattati.", "opzioni": ["Una legge sul divorzio", "Una legge tributaria", "Una legge elettorale", "Una legge sulla caccia"], "corretta": 1}, {"id": "c12-o1", "capitolo": "Cap. 12 – L'Unione europea", "giorno": 6, "tipo": "orale", "domanda": "Quali sono le tappe principali dell'integrazione europea?", "risposta": "Tutto parte dalla **Dichiarazione Schuman** del **9 maggio 1950** e dalla **CECA** del 1951. Con i **Trattati di Roma** del **1957** nascono la **CEE** e l'Euratom, con l'obiettivo del **mercato comune**. L'**Atto unico** del 1986 rilancia il mercato interno. Il **Trattato di Maastricht** del **1992** crea l'**Unione europea**, con i **tre pilastri**, la **cittadinanza europea** e la strada verso l'**euro**. Il progetto di **Costituzione europea** fallisce nel 2005. Il **Trattato di Lisbona** del **2007** supera i pilastri, dà all'UE **personalità giuridica** e alla **Carta dei diritti** lo stesso valore dei Trattati. Nel **2020** c'è la **Brexit**, che il prof considera un **disastro** per il dialogo tra **civil law e common law**.", "punti_chiave": ["Schuman e CECA", "Trattati di Roma 1957", "Maastricht 1992", "Lisbona 2007", "Brexit"]}, {"id": "c12-o2", "capitolo": "Cap. 12 – L'Unione europea", "giorno": 6, "tipo": "orale", "domanda": "Quali sono le istituzioni dell'Unione europea?", "risposta": "Il **Consiglio europeo**, formato dai **capi di Stato o di Governo**, fissa le **linee politiche** ma **non legifera**. Il **Consiglio dell'UE**, formato dai **ministri** dei vari Stati a seconda della materia, **legifera** insieme al **Parlamento europeo**, che ha **720 membri eletti dai cittadini** ogni 5 anni e controlla la Commissione. La **Commissione europea** è l'**esecutivo**, ha l'**iniziativa legislativa** ed è la **custode dei Trattati**. La **Corte di giustizia** garantisce l'**interpretazione uniforme** del diritto UE. Poi ci sono la **BCE**, per la politica monetaria, e la **Corte dei conti europea**. Attenzione a non confondere tutto questo con il **Consiglio d'Europa**, che non è un organo dell'UE.", "punti_chiave": ["Consiglio europeo: le linee politiche", "Consiglio dell'UE: i ministri", "Parlamento europeo: 720 eletti", "Commissione: esecutivo e iniziativa", "Corte di giustizia"]}, {"id": "c12-o3", "capitolo": "Cap. 12 – L'Unione europea", "giorno": 6, "tipo": "orale", "domanda": "Quali sono le fonti del diritto dell'UE?", "risposta": "Le **fonti primarie** sono i **Trattati**, cioè il **TUE** e il **TFUE**, e la **Carta dei diritti fondamentali**. Le **fonti derivate** sono gli atti delle istituzioni. I **regolamenti** sono **obbligatori in tutti i loro elementi** e **direttamente applicabili** in tutti gli Stati, senza bisogno di leggi nazionali. Le **direttive** vincolano gli Stati **solo nel risultato**, lasciando liberi i mezzi, e vanno **recepite** entro un termine. Le **decisioni** sono obbligatorie ma si rivolgono a **destinatari specifici**. Le **raccomandazioni** e i **pareri** non sono vincolanti.", "punti_chiave": ["Trattati e Carta dei diritti", "regolamenti direttamente applicabili", "direttive vincolanti nel risultato", "decisioni", "raccomandazioni e pareri"]}, {"id": "c12-o4", "capitolo": "Cap. 12 – L'Unione europea", "giorno": 6, "tipo": "orale", "domanda": "Che differenza c'è tra diretta applicabilità ed effetto diretto?", "risposta": "Sono due concetti **collegati ma diversi**. La **diretta applicabilità** è una qualità dell'**atto**: entra nell'ordinamento nazionale **senza un atto di recepimento**. Ce l'hanno i **regolamenti**. L'**effetto diretto** è una qualità della **singola norma**: il **cittadino può farla valere davanti al giudice**. Lo ha elaborato la **Corte di giustizia** e richiede che la norma sia **chiara, precisa e incondizionata**. Può averlo anche una **direttiva non recepita in tempo**, e in quel caso funziona come una **sanzione** per lo Stato inadempiente e come una **garanzia** per il cittadino.", "punti_chiave": ["diretta applicabilità: l'atto", "effetto diretto: la norma", "chiara, precisa e incondizionata", "direttiva non recepita", "Corte di giustizia"]}, {"id": "c12-o5", "capitolo": "Cap. 12 – L'Unione europea", "giorno": 6, "tipo": "orale", "domanda": "Cosa succede se una legge italiana contrasta con il diritto europeo?", "risposta": "La base costituzionale è l'**art. 11**, sulle **limitazioni di sovranità**, insieme all'**art. 117**. All'inizio la Corte costituzionale applicava il **criterio cronologico**, poi quello **gerarchico**. Con la **sentenza Granital (170/1984)** ha detto che i due ordinamenti sono **distinti ma coordinati** e che va applicato il **criterio della competenza**. Quindi: se la norma UE ha **effetto diretto**, il giudice **disapplica** la legge italiana, che **non è abrogata** ma semplicemente non si applica a quel caso. Se la norma UE **non ha effetto diretto**, il giudice solleva la questione davanti alla **Corte costituzionale**. Il limite sono i **controlimiti**: il diritto UE non può violare i **principi fondamentali** e i **diritti inviolabili**.", "punti_chiave": ["art. 11 e art. 117", "Granital 170/1984", "criterio di competenza", "disapplicazione", "controlimiti"]}, {"id": "c12-o6", "capitolo": "Cap. 12 – L'Unione europea", "giorno": 6, "tipo": "orale", "domanda": "Che cosa sono il rinvio pregiudiziale e la procedura d'infrazione?", "risposta": "Il **rinvio pregiudiziale** è lo strumento con cui un **giudice nazionale**, quando ha dubbi sull'**interpretazione** o sulla **validità** di una norma UE, chiede alla **Corte di giustizia** di pronunciarsi. Poi decide la causa sulla base della risposta. Serve a garantire un'**applicazione uniforme** del diritto UE. La **procedura d'infrazione** invece la avvia la **Commissione** contro uno **Stato** che non rispetta il diritto europeo. Ci sono una **lettera di messa in mora**, poi un **parere motivato** con un termine e, se lo Stato non si adegua, un **ricorso alla Corte di giustizia**, che può portare a **sanzioni pecuniarie**.", "punti_chiave": ["giudice nazionale e Corte di giustizia", "interpretazione e validità", "Commissione custode dei Trattati", "messa in mora e parere motivato", "sanzioni"]}, {"id": "c12-o7", "capitolo": "Cap. 12 – L'Unione europea", "giorno": 6, "tipo": "orale", "domanda": "Quali sono i principi su cui si basa l'Unione europea?", "risposta": "Il principio di **attribuzione**: l'UE può agire **solo nelle materie che gli Stati le hanno attribuito** con i Trattati, il resto resta agli Stati. Le competenze possono essere **esclusive**, **concorrenti** o **di sostegno**. Il principio di **sussidiarietà**: nelle materie non esclusive l'UE interviene solo se gli obiettivi **non possono essere raggiunti meglio dagli Stati**. Il principio di **proporzionalità**: l'UE usa **solo i mezzi necessari**. E il principio di **leale cooperazione**: Stati e Unione si aiutano reciprocamente. Questi principi servono a **limitare** il potere dell'Unione e a tenere le decisioni **vicine ai cittadini**.", "punti_chiave": ["attribuzione", "competenze esclusive e concorrenti", "sussidiarietà", "proporzionalità", "leale cooperazione"]}, {"id": "c12-f1", "capitolo": "Cap. 12 – L'Unione europea", "giorno": 6, "tipo": "flashcard", "domanda": "Regolamento UE", "risposta": "Atto obbligatorio in tutti i suoi elementi e direttamente applicabile in tutti gli Stati membri."}, {"id": "c12-f2", "capitolo": "Cap. 12 – L'Unione europea", "giorno": 6, "tipo": "flashcard", "domanda": "Direttiva UE", "risposta": "Atto che vincola gli Stati nel risultato da raggiungere, lasciando liberi forma e mezzi; va recepita."}, {"id": "c12-f3", "capitolo": "Cap. 12 – L'Unione europea", "giorno": 6, "tipo": "flashcard", "domanda": "Effetto diretto", "risposta": "Una norma UE chiara, precisa e incondizionata può essere invocata dal cittadino davanti al giudice."}, {"id": "c12-f4", "capitolo": "Cap. 12 – L'Unione europea", "giorno": 6, "tipo": "flashcard", "domanda": "Sentenza Granital (170/1984)", "risposta": "La Corte costituzionale stabilisce che il giudice disapplica la legge italiana contrastante con una norma UE direttamente efficace."}, {"id": "c12-f5", "capitolo": "Cap. 12 – L'Unione europea", "giorno": 6, "tipo": "flashcard", "domanda": "Controlimiti", "risposta": "Principi fondamentali e diritti inviolabili della Costituzione che il diritto UE non può violare."}, {"id": "c12-f6", "capitolo": "Cap. 12 – L'Unione europea", "giorno": 6, "tipo": "flashcard", "domanda": "Rinvio pregiudiziale", "risposta": "Il giudice nazionale chiede alla Corte di giustizia UE come interpretare una norma UE o se è valida."}, {"id": "c12-f7", "capitolo": "Cap. 12 – L'Unione europea", "giorno": 6, "tipo": "flashcard", "domanda": "Principio di attribuzione", "risposta": "L'UE agisce solo nei limiti delle competenze attribuitele dagli Stati con i Trattati."}, {"id": "c12-c1", "capitolo": "Cap. 12 – L'Unione europea", "giorno": 6, "tipo": "crocette", "domanda": "Chi ha l'iniziativa legislativa nell'UE (di regola)?", "risposta": "Di regola l'iniziativa spetta alla Commissione.", "opzioni": ["Il Consiglio europeo", "Il Parlamento europeo", "La Commissione europea", "La Corte di giustizia"], "corretta": 2}, {"id": "c12-c2", "capitolo": "Cap. 12 – L'Unione europea", "giorno": 6, "tipo": "crocette", "domanda": "Se una legge italiana contrasta con un regolamento UE direttamente efficace, il giudice…", "risposta": "La disapplica (Granital 1984): la legge resta valida ma non si applica al caso.", "opzioni": ["la abroga", "la disapplica", "la annulla", "la rinvia al Parlamento"], "corretta": 1}, {"id": "c12-c3", "capitolo": "Cap. 12 – L'Unione europea", "giorno": 6, "tipo": "crocette", "domanda": "Il Consiglio europeo è composto da…", "risposta": "Capi di Stato o di Governo; i ministri formano il Consiglio dell'UE.", "opzioni": ["i ministri degli Stati membri", "i capi di Stato o di Governo", "i deputati europei", "i commissari"], "corretta": 1}, {"id": "c13-o1", "capitolo": "Cap. 13 – Il bilancio", "giorno": 6, "tipo": "orale", "domanda": "Che cosa dice la Costituzione sulle tasse?", "risposta": "L'**art. 53** stabilisce che **tutti** devono concorrere alle spese pubbliche **in ragione della loro capacità contributiva**, e che il sistema tributario è informato a criteri di **progressività**: chi ha di più paga **in proporzione di più**. La capacità contributiva esprime l'**uguaglianza formale**, la progressività l'**uguaglianza sostanziale** dell'art. 3. L'**art. 23** prevede una **riserva di legge** (relativa): nessuna prestazione patrimoniale può essere imposta **se non in base alla legge**. Infine il prof collega le tasse alla **sovranità**: senza il potere di imporre tributi lo Stato non può esercitare davvero il suo potere.", "punti_chiave": ["art. 53", "capacità contributiva", "progressività", "art. 23 riserva di legge", "sovranità e tasse"]}, {"id": "c13-o2", "capitolo": "Cap. 13 – Il bilancio", "giorno": 6, "tipo": "orale", "domanda": "Che cosa prevede oggi l'art. 81 della Costituzione?", "risposta": "Con la **legge costituzionale 1/2012** l'art. 81 impone l'**equilibrio tra entrate e spese**, **tenendo conto delle fasi del ciclo economico**. Il **ricorso all'indebitamento** è consentito **solo** per considerare gli **effetti del ciclo economico** e, in caso di **eventi eccezionali** come gravi recessioni, crisi finanziarie o catastrofi, **previa autorizzazione delle Camere a maggioranza assoluta**. L'equilibrio vale anche per le **pubbliche amministrazioni** e gli **enti territoriali**. Resta l'**obbligo di copertura**: ogni legge che comporta nuove spese deve indicare **i mezzi per farvi fronte**. La riforma nasce dalla **crisi del debito del 2011** e dal **Fiscal compact**.", "punti_chiave": ["equilibrio di bilancio", "ciclo economico", "eventi eccezionali e maggioranza assoluta", "obbligo di copertura", "Fiscal compact"]}, {"id": "c13-o3", "capitolo": "Cap. 13 – Il bilancio", "giorno": 6, "tipo": "orale", "domanda": "Come funziona il ciclo di bilancio?", "risposta": "In primavera il Governo presenta il **Documento di finanza pubblica**, che si inserisce nel **Piano strutturale di bilancio di medio termine** richiesto dall'UE. In autunno il **Documento programmatico di finanza pubblica**, che dal 2025 ha sostituito la NaDEF, prepara la manovra. **Entro il 15 ottobre** il Governo presenta il **disegno di legge di bilancio**, che le Camere devono approvare **entro il 31 dicembre**, così da entrare in vigore il 1° gennaio. La legge di bilancio ha **due sezioni**: la prima con le **misure** della manovra, la seconda **contabile**. Se non viene approvata in tempo, c'è l'**esercizio provvisorio**, autorizzato **con legge** per **massimo 4 mesi**.", "punti_chiave": ["DFP e DPFP", "15 ottobre – 31 dicembre", "due sezioni", "esercizio provvisorio di 4 mesi"]}, {"id": "c13-o4", "capitolo": "Cap. 13 – Il bilancio", "giorno": 6, "tipo": "orale", "domanda": "Quali vincoli pone l'Unione europea ai bilanci nazionali?", "risposta": "Dal **Trattato di Maastricht** gli Stati devono evitare **disavanzi eccessivi**. I parametri di riferimento sono il **3% del PIL per il deficit** e il **60% del PIL per il debito**. Poi sono arrivati il **Patto di stabilità e crescita** (1997) e, dopo la crisi del debito, il **Semestre europeo**, il **Six pack** e il **Fiscal compact** del 2012, che impone il **pareggio di bilancio** e ha portato alla riforma dell'art. 81. **Dal 2024** le regole sono state riformate: il controllo si basa su **piani strutturali di bilancio di medio termine** e sull'andamento della **spesa netta**. Il punto debole è che la **politica monetaria è comune** mentre quella di **bilancio resta nazionale**.", "punti_chiave": ["3% deficit e 60% debito", "Patto di stabilità", "Fiscal compact", "riforma 2024", "moneta comune e bilancio nazionale"]}, {"id": "c13-o5", "capitolo": "Cap. 13 – Il bilancio", "giorno": 6, "tipo": "orale", "domanda": "Che differenza c'è tra deficit e debito pubblico?", "risposta": "Il **deficit**, o **disavanzo**, è la situazione in cui **in un anno** lo Stato **spende più di quanto incassa**. Il **debito pubblico** è invece **l'insieme di tutto ciò che lo Stato deve** ai suoi creditori, **accumulato negli anni**, soprattutto attraverso i **titoli di Stato**. Si misurano entrambi in rapporto al **PIL**, che è il valore di tutti i beni e servizi prodotti nel Paese in un anno. Se il debito è troppo alto, i mercati chiedono **interessi più alti** e si crea un **circolo vizioso**, come nella crisi del **2011** in Italia.", "punti_chiave": ["deficit annuale", "debito accumulato", "rapporto con il PIL", "interessi e spread", "circolo vizioso"]}, {"id": "c13-f1", "capitolo": "Cap. 13 – Il bilancio", "giorno": 6, "tipo": "flashcard", "domanda": "Capacità contributiva (art. 53)", "risposta": "Ciascuno concorre alle spese pubbliche in base alla propria ricchezza; il sistema è progressivo."}, {"id": "c13-f2", "capitolo": "Cap. 13 – Il bilancio", "giorno": 6, "tipo": "flashcard", "domanda": "Equilibrio di bilancio", "risposta": "Art. 81 (dal 2012): equilibrio tra entrate e spese tenendo conto del ciclo economico; debito solo in casi limitati."}, {"id": "c13-f3", "capitolo": "Cap. 13 – Il bilancio", "giorno": 6, "tipo": "flashcard", "domanda": "Esercizio provvisorio", "risposta": "Se il bilancio non è approvato entro il 31 dicembre, le Camere lo autorizzano con legge per massimo 4 mesi."}, {"id": "c13-f4", "capitolo": "Cap. 13 – Il bilancio", "giorno": 6, "tipo": "flashcard", "domanda": "Obbligo di copertura", "risposta": "Ogni legge che comporta nuove spese deve indicare i mezzi per farvi fronte (art. 81)."}, {"id": "c13-f5", "capitolo": "Cap. 13 – Il bilancio", "giorno": 6, "tipo": "flashcard", "domanda": "Fiscal compact", "risposta": "Trattato del 2012 che impone il pareggio di bilancio; ha portato alla riforma dell'art. 81."}, {"id": "c13-f6", "capitolo": "Cap. 13 – Il bilancio", "giorno": 6, "tipo": "flashcard", "domanda": "Deficit / disavanzo", "risposta": "Situazione in cui, in un anno, le spese pubbliche superano le entrate."}, {"id": "c13-c1", "capitolo": "Cap. 13 – Il bilancio", "giorno": 6, "tipo": "crocette", "domanda": "Entro quando il Governo presenta il disegno di legge di bilancio?", "risposta": "Entro il 15 ottobre; va approvato entro il 31 dicembre.", "opzioni": ["31 marzo", "15 luglio", "15 ottobre", "31 dicembre"], "corretta": 2}, {"id": "c13-c2", "capitolo": "Cap. 13 – Il bilancio", "giorno": 6, "tipo": "crocette", "domanda": "L'esercizio provvisorio può durare al massimo…", "risposta": "Al massimo 4 mesi, autorizzato con legge.", "opzioni": ["2 mesi", "4 mesi", "6 mesi", "12 mesi"], "corretta": 1}, {"id": "c13-c3", "capitolo": "Cap. 13 – Il bilancio", "giorno": 6, "tipo": "crocette", "domanda": "Per l'art. 81 lo Stato può indebitarsi per eventi eccezionali con l'autorizzazione delle Camere a…", "risposta": "Serve la maggioranza assoluta dei componenti.", "opzioni": ["maggioranza semplice", "maggioranza assoluta", "maggioranza dei 2/3", "unanimità"], "corretta": 1}, {"id": "c14-o1", "capitolo": "Cap. 14 – Regioni ed enti locali", "giorno": 7, "tipo": "orale", "domanda": "Che cosa ha cambiato la riforma del Titolo V del 2001?", "risposta": "La **legge costituzionale 3/2001** ha creato una **Repubblica delle autonomie**. L'**art. 114** dice che la Repubblica è costituita da **Comuni, Province, Città metropolitane, Regioni e Stato**: c'è un'**equiordinazione**, cioè lo Stato non sta più sopra gli altri enti. L'**art. 117** ha **ribaltato** il riparto delle leggi: ora c'è un elenco di materie per lo **Stato** e **tutto il resto va alle Regioni**. L'**art. 118** affida le funzioni amministrative **di norma ai Comuni**, secondo la **sussidiarietà**. L'**art. 119** introduce il **federalismo fiscale**. Sono stati eliminati anche i **controlli preventivi** sulle leggi regionali.", "punti_chiave": ["legge cost. 3/2001", "art. 114 ed equiordinazione", "art. 117 ribaltato", "art. 118 e sussidiarietà", "federalismo fiscale"]}, {"id": "c14-o2", "capitolo": "Cap. 14 – Regioni ed enti locali", "giorno": 7, "tipo": "orale", "domanda": "Come sono ripartite le competenze legislative tra Stato e Regioni?", "risposta": "L'**art. 117** prevede tre tipi di competenza. La competenza **esclusiva dello Stato** è un elenco di materie in cui legifera **solo lo Stato**: esteri, difesa, moneta, giustizia, ordine pubblico, **concorrenza**, **ambiente**. La competenza **concorrente** è un elenco di materie in cui lo **Stato fissa i principi fondamentali**, con le **leggi-cornice**, e le **Regioni** fanno la **disciplina di dettaglio**: per esempio salute, istruzione, governo del territorio. La competenza **residuale**: **tutto ciò che non è elencato** spetta alle **Regioni**. La legge regionale è **pari** a quella statale e si usa il **criterio di competenza**. Entrambe rispettano **Costituzione, UE e obblighi internazionali**.", "punti_chiave": ["esclusiva dello Stato", "concorrente e leggi-cornice", "residuale delle Regioni", "legge regionale pari a quella statale", "criterio di competenza"]}, {"id": "c14-o3", "capitolo": "Cap. 14 – Regioni ed enti locali", "giorno": 7, "tipo": "orale", "domanda": "Che cos'è il principio di sussidiarietà?", "risposta": "La **sussidiarietà verticale** (art. 118) dice che le funzioni amministrative spettano **di norma ai Comuni**, l'ente più **vicino ai cittadini**, e salgono a Province, Regioni o Stato **solo se serve un esercizio unitario**. Si accompagna ai principi di **differenziazione** (enti dello stesso livello possono avere funzioni diverse) e di **adeguatezza** (la funzione va all'ente capace di esercitarla). La **sussidiarietà orizzontale** (art. 118 ultimo comma) dice che Stato ed enti **favoriscono l'iniziativa dei cittadini**, singoli e associati, per attività di **interesse generale**: ciò che i privati e il volontariato fanno bene, il pubblico non deve fare. Lo stesso principio vale anche nell'**Unione europea**.", "punti_chiave": ["sussidiarietà verticale", "di norma ai Comuni", "differenziazione e adeguatezza", "sussidiarietà orizzontale", "interesse generale"]}, {"id": "c14-o4", "capitolo": "Cap. 14 – Regioni ed enti locali", "giorno": 7, "tipo": "orale", "domanda": "Qual è la forma di governo delle Regioni?", "risposta": "Gli organi sono tre: il **Consiglio regionale**, che fa le leggi; la **Giunta**, che è l'esecutivo; e il **Presidente della Regione**, che dalla **legge costituzionale 1/1999** è **eletto direttamente** dai cittadini (salvo una diversa scelta dello Statuto). Il Presidente **nomina e revoca** la Giunta, **promulga le leggi** ed emana i regolamenti. Vale il principio **simul stabunt, simul cadent**: se il Presidente viene **sfiduciato**, si dimette o muore, **cadono anche Giunta e Consiglio** e si torna a votare. L'obiettivo è dare **stabilità** ed evitare cambi di maggioranza durante la legislatura. Assomiglia al modello **neoparlamentare**.", "punti_chiave": ["Consiglio, Giunta, Presidente", "elezione diretta (1999)", "simul stabunt simul cadent", "stabilità", "neoparlamentare"]}, {"id": "c14-o5", "capitolo": "Cap. 14 – Regioni ed enti locali", "giorno": 7, "tipo": "orale", "domanda": "Che differenza c'è tra Regioni ordinarie e Regioni speciali?", "risposta": "Le **Regioni a statuto speciale** sono cinque: **Sicilia, Sardegna, Valle d'Aosta, Trentino-Alto Adige e Friuli-Venezia Giulia**, più le **Province autonome di Trento e Bolzano**. Hanno un'**autonomia più ampia** per ragioni storiche, linguistiche o geografiche, e il loro **Statuto è approvato con legge costituzionale** (art. 116). Le **Regioni ordinarie** sono 15. Sono nate davvero solo nel **1970** e il loro **Statuto** lo approva il **Consiglio regionale** con legge a **maggioranza assoluta**, con **due deliberazioni a distanza di 2 mesi**. Il Governo può impugnarlo entro **30 giorni** e si può chiedere un **referendum** regionale (art. 123).", "punti_chiave": ["5 speciali e Trento e Bolzano", "Statuto con legge costituzionale", "15 ordinarie dal 1970", "Statuto: 2 deliberazioni a maggioranza assoluta", "art. 123"]}, {"id": "c14-o6", "capitolo": "Cap. 14 – Regioni ed enti locali", "giorno": 7, "tipo": "orale", "domanda": "Come funziona il Comune e come si elegge il sindaco?", "risposta": "Il **sindaco** è **eletto direttamente** dal **1993**: è stato il primo caso in Italia di elezione diretta del capo dell'esecutivo. Gli organi sono il **sindaco**, la **Giunta**, che collabora con lui, e il **Consiglio comunale**, che ha funzioni di **indirizzo e controllo**. Anche qui vale **simul stabunt, simul cadent**: se il Consiglio approva la **sfiducia** cadono sindaco, Giunta e Consiglio. Nei Comuni **sotto i 15.000 abitanti** c'è un **turno unico** e vince chi prende più voti. **Sopra i 15.000** è ammesso il **voto disgiunto** e, se nessuno supera il 50%, si va al **ballottaggio**, con un premio di maggioranza alla coalizione del vincitore.", "punti_chiave": ["elezione diretta dal 1993", "sindaco, Giunta, Consiglio", "simul stabunt simul cadent", "15.000 abitanti", "voto disgiunto e ballottaggio"]}, {"id": "c14-f1", "capitolo": "Cap. 14 – Regioni ed enti locali", "giorno": 7, "tipo": "flashcard", "domanda": "Equiordinazione (art. 114)", "risposta": "Comuni, Province, Città metropolitane, Regioni e Stato sono componenti della Repubblica di pari dignità."}, {"id": "c14-f2", "capitolo": "Cap. 14 – Regioni ed enti locali", "giorno": 7, "tipo": "flashcard", "domanda": "Competenza concorrente", "risposta": "Lo Stato fissa i principi fondamentali (leggi-cornice), le Regioni la disciplina di dettaglio."}, {"id": "c14-f3", "capitolo": "Cap. 14 – Regioni ed enti locali", "giorno": 7, "tipo": "flashcard", "domanda": "Competenza residuale", "risposta": "Tutte le materie non elencate nell'art. 117 spettano alle Regioni."}, {"id": "c14-f4", "capitolo": "Cap. 14 – Regioni ed enti locali", "giorno": 7, "tipo": "flashcard", "domanda": "Simul stabunt, simul cadent", "risposta": "Se cade il Presidente della Regione (o il sindaco) cadono anche Giunta e Consiglio e si torna al voto."}, {"id": "c14-f5", "capitolo": "Cap. 14 – Regioni ed enti locali", "giorno": 7, "tipo": "flashcard", "domanda": "Materie trasversali", "risposta": "Competenze statali come concorrenza e ambiente che incidono anche sulle materie regionali."}, {"id": "c14-f6", "capitolo": "Cap. 14 – Regioni ed enti locali", "giorno": 7, "tipo": "flashcard", "domanda": "Sussidiarietà verticale", "risposta": "Le funzioni amministrative spettano di norma ai Comuni e salgono di livello solo se necessario."}, {"id": "c14-c1", "capitolo": "Cap. 14 – Regioni ed enti locali", "giorno": 7, "tipo": "crocette", "domanda": "In quale anno è stata approvata la riforma del Titolo V?", "risposta": "Legge costituzionale 3/2001.", "opzioni": ["1970", "1999", "2001", "2016"], "corretta": 2}, {"id": "c14-c2", "capitolo": "Cap. 14 – Regioni ed enti locali", "giorno": 7, "tipo": "crocette", "domanda": "Nelle materie di competenza concorrente…", "risposta": "Lo Stato fa le leggi-cornice, la Regione la disciplina di dettaglio.", "opzioni": ["legifera solo lo Stato", "legifera solo la Regione", "lo Stato fissa i principi, la Regione il dettaglio", "decide la Corte costituzionale"], "corretta": 2}, {"id": "c14-c3", "capitolo": "Cap. 14 – Regioni ed enti locali", "giorno": 7, "tipo": "crocette", "domanda": "Lo Statuto delle Regioni speciali è approvato con…", "risposta": "Con legge costituzionale (art. 116).", "opzioni": ["legge regionale", "legge ordinaria dello Stato", "legge costituzionale", "regolamento"], "corretta": 2}, {"id": "c15-o1", "capitolo": "Cap. 15 – La Pubblica Amministrazione", "giorno": 7, "tipo": "orale", "domanda": "Quali sono i principi costituzionali sulla Pubblica Amministrazione?", "risposta": "Il principio centrale è la **legalità**: la PA agisce **solo nei casi e nei modi previsti dalla legge**. L'**art. 97** aggiunge l'**imparzialità**, cioè niente favoritismi, e il **buon andamento**, cioè **efficienza, efficacia ed economicità**. Prevede anche una **riserva di legge relativa** sull'organizzazione degli uffici e il **concorso pubblico** per entrare nella PA, oltre all'**equilibrio dei bilanci**. L'**art. 28** stabilisce la **responsabilità diretta** dei dipendenti pubblici per gli atti che violano i diritti, insieme allo Stato. Infine c'è la **separazione tra politica e amministrazione**: la politica fissa gli **obiettivi**, i **dirigenti** gestiscono.", "punti_chiave": ["legalità", "imparzialità e buon andamento (art. 97)", "concorso pubblico", "responsabilità (art. 28)", "separazione politica-amministrazione"]}, {"id": "c15-o2", "capitolo": "Cap. 15 – La Pubblica Amministrazione", "giorno": 7, "tipo": "orale", "domanda": "Che cosa prevede la legge 241 del 1990?", "risposta": "È la legge generale sul **procedimento amministrativo**. Prevede l'**obbligo di concludere** ogni procedimento con un **provvedimento espresso** e **entro un termine**. Ogni procedimento ha un **responsabile**. C'è la **comunicazione di avvio** e il **diritto di partecipazione**: gli interessati possono presentare **memorie e documenti**, che la PA deve valutare. Ogni provvedimento deve essere **motivato**, con le ragioni di fatto e di diritto. C'è il **diritto di accesso** agli atti per chi ha un interesse diretto. E ci sono strumenti di **semplificazione**: la **conferenza di servizi**, la **SCIA** e il **silenzio-assenso**.", "punti_chiave": ["procedimento amministrativo", "dovere di concludere entro un termine", "responsabile del procedimento", "partecipazione", "motivazione", "semplificazione"]}, {"id": "c15-o3", "capitolo": "Cap. 15 – La Pubblica Amministrazione", "giorno": 7, "tipo": "orale", "domanda": "Quali sono le caratteristiche del provvedimento amministrativo?", "risposta": "Il provvedimento è l'atto con cui la PA **decide**, producendo **effetti esterni**. È **unilaterale**, o **autoritativo**: produce effetti **anche senza il consenso** del destinatario. È **tipico**: la PA può adottare **solo i provvedimenti previsti dalla legge** e per lo scopo previsto, ed è una conseguenza della **legalità**. È **esecutivo**, cioè **efficace subito**, senza bisogno del giudice. Ed è **esecutorio**: la PA può **imporlo coattivamente** da sola, in **autotutela**, nei casi previsti. I provvedimenti possono essere **favorevoli**, come autorizzazioni e concessioni, o **sfavorevoli**, come espropri e sanzioni.", "punti_chiave": ["unilateralità", "tipicità", "esecutività", "esecutorietà", "favorevoli e sfavorevoli"]}, {"id": "c15-o4", "capitolo": "Cap. 15 – La Pubblica Amministrazione", "giorno": 7, "tipo": "orale", "domanda": "Quali sono i vizi del provvedimento amministrativo?", "risposta": "Nei casi più gravi c'è la **nullità**: quando **mancano elementi essenziali**, quando c'è un **difetto assoluto di attribuzione** (la PA non ha quel potere) o quando si **viola un giudicato**. Il provvedimento nullo **non produce effetti**. Più spesso c'è l'**annullabilità** per **vizi di legittimità**. Il primo è l'**incompetenza**: l'atto è emanato dall'organo sbagliato della stessa PA. Il secondo è la **violazione di legge**. Il terzo è l'**eccesso di potere**, cioè il cattivo uso della discrezionalità, che si riconosce dalle **figure sintomatiche**: **sviamento di potere**, travisamento dei fatti, illogicità, **disparità di trattamento**, **difetto di motivazione**. Gli atti illegittimi si impugnano davanti al **TAR**.", "punti_chiave": ["nullità", "annullabilità", "incompetenza", "violazione di legge", "eccesso di potere e figure sintomatiche", "TAR"]}, {"id": "c15-o5", "capitolo": "Cap. 15 – La Pubblica Amministrazione", "giorno": 7, "tipo": "orale", "domanda": "Che differenza c'è tra diritto soggettivo e interesse legittimo?", "risposta": "Il **diritto soggettivo** è una posizione di vantaggio **piena**, tutelata **direttamente** dall'ordinamento: per esempio la proprietà. L'**interesse legittimo** è la posizione del privato **davanti al potere della PA**: non può pretendere un certo risultato, ma ha diritto a che la PA **eserciti il potere legittimamente**. Se l'atto è illegittimo, può farlo **annullare**. Per esempio, davanti a un **esproprio** il diritto di proprietà si **degrada** a interesse legittimo. La distinzione serve per il **riparto di giurisdizione**: per i diritti soggettivi si va dal **giudice ordinario**, per gli interessi legittimi dal **giudice amministrativo**, cioè **TAR e Consiglio di Stato**.", "punti_chiave": ["diritto soggettivo", "interesse legittimo", "degradazione con l'esproprio", "riparto di giurisdizione", "TAR e Consiglio di Stato"]}, {"id": "c15-o6", "capitolo": "Cap. 15 – La Pubblica Amministrazione", "giorno": 7, "tipo": "orale", "domanda": "Che differenza c'è tra annullamento d'ufficio e revoca?", "risposta": "Sono entrambi strumenti di **autotutela**, con cui la PA corregge da sola i propri atti. L'**annullamento d'ufficio** riguarda un atto **illegittimo**: la PA lo elimina, ma solo se c'è un **interesse pubblico attuale** a farlo (non basta l'illegittimità) ed entro un termine ragionevole. L'effetto è **retroattivo**. La **revoca** riguarda invece un atto **valido**, che però **non è più opportuno** per un **mutamento dell'interesse pubblico** o della situazione. Vale **per il futuro** e può comportare un **indennizzo** per chi ci perde. Per i vizi più lievi la PA può invece **sanare** l'atto con **convalida** o **ratifica**.", "punti_chiave": ["autotutela", "annullamento: atto illegittimo", "interesse pubblico", "revoca: atto non più opportuno", "indennizzo", "convalida e ratifica"]}, {"id": "c15-o7", "capitolo": "Cap. 15 – La Pubblica Amministrazione", "giorno": 7, "tipo": "orale", "domanda": "Che cosa sono le Autorità amministrative indipendenti?", "risposta": "Sono autorità pubbliche **indipendenti dal Governo**, con un alto livello di **competenza tecnica**. Sono nate con privatizzazioni, liberalizzazioni e integrazione europea, quando lo Stato è passato da **imprenditore** a **regolatore**. Tutelano **interessi costituzionali** come la concorrenza, il risparmio e la privacy, in modo **neutrale**. La loro indipendenza è garantita dal legame con il **Parlamento** e dall'**autonomia** organizzativa e finanziaria. Hanno poteri di **regolazione**, di **sanzione** e di risoluzione delle controversie. Le principali sono l'**Antitrust**, che vieta **intese**, **abuso di posizione dominante** e **concentrazioni** anticoncorrenziali, la **CONSOB**, il **Garante privacy** e l'**ANAC**.", "punti_chiave": ["indipendenza dal Governo", "Stato regolatore", "tutela di interessi costituzionali", "Antitrust", "CONSOB, Garante privacy, ANAC"]}, {"id": "c15-f1", "capitolo": "Cap. 15 – La Pubblica Amministrazione", "giorno": 7, "tipo": "flashcard", "domanda": "Buon andamento (art. 97)", "risposta": "Principio per cui la PA deve agire con efficienza, efficacia ed economicità."}, {"id": "c15-f2", "capitolo": "Cap. 15 – La Pubblica Amministrazione", "giorno": 7, "tipo": "flashcard", "domanda": "Silenzio-assenso", "risposta": "In certi casi, se la PA non risponde entro il termine, la domanda si considera accolta."}, {"id": "c15-f3", "capitolo": "Cap. 15 – La Pubblica Amministrazione", "giorno": 7, "tipo": "flashcard", "domanda": "SCIA", "risposta": "Segnalazione certificata di inizio attività: si avvia un'attività con una segnalazione, senza attendere un'autorizzazione."}, {"id": "c15-f4", "capitolo": "Cap. 15 – La Pubblica Amministrazione", "giorno": 7, "tipo": "flashcard", "domanda": "Eccesso di potere", "risposta": "Vizio di legittimità per cattivo uso della discrezionalità (sviamento, illogicità, disparità di trattamento…)."}, {"id": "c15-f5", "capitolo": "Cap. 15 – La Pubblica Amministrazione", "giorno": 7, "tipo": "flashcard", "domanda": "Interesse legittimo", "risposta": "Posizione del privato di fronte al potere della PA: pretesa che il potere sia esercitato legittimamente."}, {"id": "c15-f6", "capitolo": "Cap. 15 – La Pubblica Amministrazione", "giorno": 7, "tipo": "flashcard", "domanda": "Revoca", "risposta": "Ritiro di un atto valido divenuto inopportuno per mutamento dell'interesse pubblico; può dare luogo a indennizzo."}, {"id": "c15-f7", "capitolo": "Cap. 15 – La Pubblica Amministrazione", "giorno": 7, "tipo": "flashcard", "domanda": "Accesso civico generalizzato (FOIA)", "risposta": "Chiunque può chiedere dati e documenti alla PA senza motivare; risposta entro 30 giorni."}, {"id": "c15-c1", "capitolo": "Cap. 15 – La Pubblica Amministrazione", "giorno": 7, "tipo": "crocette", "domanda": "Il ricorso straordinario al Presidente della Repubblica si propone entro…", "risposta": "Entro 120 giorni, in alternativa al ricorso al TAR.", "opzioni": ["30 giorni", "60 giorni", "120 giorni", "1 anno"], "corretta": 2}, {"id": "c15-c2", "capitolo": "Cap. 15 – La Pubblica Amministrazione", "giorno": 7, "tipo": "crocette", "domanda": "Lo sviamento di potere è una figura sintomatica di…", "risposta": "È la principale figura sintomatica dell'eccesso di potere.", "opzioni": ["incompetenza", "violazione di legge", "eccesso di potere", "nullità"], "corretta": 2}, {"id": "c15-c3", "capitolo": "Cap. 15 – La Pubblica Amministrazione", "giorno": 7, "tipo": "crocette", "domanda": "Chi tutela gli interessi legittimi in primo grado?", "risposta": "Il TAR; in appello il Consiglio di Stato.", "opzioni": ["Il Tribunale civile", "Il TAR", "La Corte dei conti", "La Cassazione"], "corretta": 1}, {"id": "c16-o1", "capitolo": "Cap. 16 – Diritti e libertà", "giorno": 8, "tipo": "orale", "domanda": "Che cosa dice l'art. 2 della Costituzione?", "risposta": "L'**art. 2** enuncia il principio **personalista** e quello **pluralista**. La Repubblica **riconosce e garantisce i diritti inviolabili dell'uomo**, sia **come singolo** sia nelle **formazioni sociali** dove si svolge la sua personalità: famiglia, associazioni, partiti, sindacati, confessioni. Dice **riconosce**, quindi i diritti **esistono prima** dello Stato, e dice **dell'uomo**, quindi valgono anche per gli **stranieri**. L'articolo chiede anche l'adempimento dei **doveri inderogabili di solidarietà** politica, economica e sociale. Si discute se sia un **catalogo aperto**, che permette di riconoscere **nuovi diritti**: la Corte preferisce collegarli a diritti già scritti.", "punti_chiave": ["diritti inviolabili", "riconosce e garantisce", "formazioni sociali", "doveri di solidarietà", "catalogo aperto o chiuso"]}, {"id": "c16-o2", "capitolo": "Cap. 16 – Diritti e libertà", "giorno": 8, "tipo": "orale", "domanda": "Mi spieghi il principio di uguaglianza.", "risposta": "L'**art. 3** prevede due uguaglianze. Quella **formale** (comma 1): tutti hanno **pari dignità sociale** e sono **uguali davanti alla legge**, senza distinzioni di **sesso, razza, lingua, religione, opinioni politiche, condizioni personali e sociali**. Significa trattare in modo **uguale situazioni uguali** e in modo **diverso situazioni diverse**, e la Corte lo verifica con il **giudizio di ragionevolezza**. Quella **sostanziale** (comma 2): la Repubblica deve **rimuovere gli ostacoli economici e sociali** che **di fatto** limitano libertà e uguaglianza. Permette le **azioni positive**. Le due uguaglianze **non si contraddicono ma si completano**. Il prof aggiunge che gli **artt. 1, 2 e 3 sono una triade inseparabile**.", "punti_chiave": ["uguaglianza formale", "divieto di discriminazioni", "ragionevolezza", "uguaglianza sostanziale e rimozione degli ostacoli", "azioni positive", "triade artt. 1-2-3"]}, {"id": "c16-o3", "capitolo": "Cap. 16 – Diritti e libertà", "giorno": 8, "tipo": "orale", "domanda": "Come è tutelata la libertà personale?", "risposta": "L'**art. 13** dice che la libertà personale è **inviolabile**. È l'**habeas corpus**, la libertà fisica. Non sono ammesse detenzione, ispezione, perquisizione o altre restrizioni **se non per atto motivato dell'autorità giudiziaria** (è la **riserva di giurisdizione**) e **nei soli casi e modi previsti dalla legge** (è la **riserva di legge assoluta**). Nei casi eccezionali di **necessità e urgenza** la **polizia** può adottare provvedimenti provvisori, come l'**arresto in flagranza**, ma deve comunicarli al giudice **entro 48 ore**, e il giudice deve **convalidarli nelle 48 ore successive**, altrimenti **perdono effetto**. È punita ogni violenza su chi è privato della libertà. L'**art. 27** aggiunge la presunzione di non colpevolezza, la funzione **rieducativa** della pena e il **divieto della pena di morte**.", "punti_chiave": ["art. 13 inviolabile", "riserva di legge assoluta", "riserva di giurisdizione", "48 + 48 ore", "art. 27"]}, {"id": "c16-o4", "capitolo": "Cap. 16 – Diritti e libertà", "giorno": 8, "tipo": "orale", "domanda": "Che differenza c'è tra libertà di riunione e libertà di associazione?", "risposta": "La **riunione** (art. 17) è una **compresenza temporanea** di persone per uno scopo comune. Deve avvenire **pacificamente e senza armi**. In un luogo **pubblico** serve solo un **preavviso** alla Questura, **non un'autorizzazione**, e può essere vietata solo per **comprovati motivi di sicurezza o incolumità pubblica**. In un luogo privato o aperto al pubblico non serve nulla. L'**associazione** (art. 18) ha invece un'**organizzazione stabile**. È **libera, senza autorizzazione**, per fini **non vietati ai singoli dalla legge penale**, e **nessuno può essere obbligato** ad associarsi. Sono vietate le associazioni **segrete** e quelle **paramilitari** con fini politici.", "punti_chiave": ["riunione temporanea", "preavviso e non autorizzazione", "associazione stabile", "libertà negativa", "segrete e paramilitari vietate"]}, {"id": "c16-o5", "capitolo": "Cap. 16 – Diritti e libertà", "giorno": 8, "tipo": "orale", "domanda": "Che cosa garantisce l'art. 21 sulla libertà di manifestazione del pensiero?", "risposta": "L'**art. 21** garantisce a **tutti** il diritto di manifestare il proprio pensiero con la **parola, lo scritto e ogni altro mezzo**. È il **cardine della democrazia**. L'unico **limite esplicito** è il **buon costume**. Altri limiti vengono dal bilanciamento con l'**onore**, cioè la diffamazione, e dal divieto di **istigazione** a commettere reati. Per la **stampa** sono vietate **autorizzazioni e censure**. Il **sequestro** è ammesso solo con **atto motivato del giudice** nei casi previsti dalla legge. Nei casi urgenti può procedere la **polizia giudiziaria**, che informa il giudice **entro 24 ore**, e il giudice convalida entro **altre 24 ore**. La stampa non può essere anonima e va garantito il **pluralismo dell'informazione**.", "punti_chiave": ["parola, scritto, ogni mezzo", "limite del buon costume", "no autorizzazioni o censure", "sequestro 24 + 24 ore", "pluralismo"]}, {"id": "c16-o6", "capitolo": "Cap. 16 – Diritti e libertà", "giorno": 8, "tipo": "orale", "domanda": "Che cos'è il bilanciamento dei diritti?", "risposta": "I diritti costituzionali sono scritti come **principi**: non hanno una **gerarchia** tra loro e in astratto non si contraddicono. In **concreto** però possono **scontrarsi**: per esempio il diritto di **cronaca** con la **riservatezza**, o la **salute della madre** con la **vita del nascituro**. La **Corte costituzionale** usa allora il **bilanciamento**: valuta caso per caso quale interesse prevale e in che misura, **senza sacrificarne del tutto** nessuno. Un esempio famoso è la sentenza del **1975** sull'aborto: non c'è equivalenza tra la madre, che **è già persona**, e l'embrione, che **deve ancora diventarlo**. Da qui poi la legge 194/1978. Il criterio guida è la **ragionevolezza**.", "punti_chiave": ["principi senza gerarchia", "conflitto in concreto", "bilanciamento caso per caso", "sentenza 1975 sull'aborto", "ragionevolezza"]}, {"id": "c16-o7", "capitolo": "Cap. 16 – Diritti e libertà", "giorno": 8, "tipo": "orale", "domanda": "Quali sono i principali diritti sociali?", "risposta": "I **diritti sociali** sono diritti a ricevere **prestazioni** dallo Stato, tipici dello **Stato sociale**. Il più importante è la **salute** (art. 32), l'**unico diritto che la Costituzione chiama fondamentale**: spetta a tutti, prevede **cure gratuite agli indigenti** e vieta i **trattamenti sanitari obbligatori** se non previsti dalla legge e nel rispetto della persona. Poi c'è l'**istruzione** (artt. 33–34): scuola aperta a tutti, obbligatoria e gratuita per almeno 8 anni, e diritto dei **capaci e meritevoli**, anche se privi di mezzi, ai gradi più alti degli studi. C'è la **previdenza e assistenza** (art. 38). Oggi la Corte riconosce loro un **contenuto minimo essenziale** che il legislatore non può eliminare.", "punti_chiave": ["prestazioni dello Stato", "salute fondamentale (art. 32)", "istruzione e merito (art. 34)", "previdenza e assistenza (art. 38)", "contenuto minimo essenziale"]}, {"id": "c16-f1", "capitolo": "Cap. 16 – Diritti e libertà", "giorno": 8, "tipo": "flashcard", "domanda": "Riserva di giurisdizione", "risposta": "Per limitare certe libertà serve un atto motivato dell'autorità giudiziaria (artt. 13, 14, 15, 21)."}, {"id": "c16-f2", "capitolo": "Cap. 16 – Diritti e libertà", "giorno": 8, "tipo": "flashcard", "domanda": "Uguaglianza sostanziale", "risposta": "Art. 3 c. 2: la Repubblica rimuove gli ostacoli economici e sociali che limitano di fatto libertà e uguaglianza."}, {"id": "c16-f3", "capitolo": "Cap. 16 – Diritti e libertà", "giorno": 8, "tipo": "flashcard", "domanda": "Habeas corpus", "risposta": "La libertà personale come libertà fisica dalla coercizione (art. 13)."}, {"id": "c16-f4", "capitolo": "Cap. 16 – Diritti e libertà", "giorno": 8, "tipo": "flashcard", "domanda": "Formazioni sociali", "risposta": "Organizzazioni tra individuo e Stato (famiglia, partiti, sindacati…) in cui si svolge la personalità (art. 2)."}, {"id": "c16-f5", "capitolo": "Cap. 16 – Diritti e libertà", "giorno": 8, "tipo": "flashcard", "domanda": "Bilanciamento", "risposta": "Tecnica con cui la Corte risolve i conflitti tra diritti decidendo caso per caso quale prevale."}, {"id": "c16-f6", "capitolo": "Cap. 16 – Diritti e libertà", "giorno": 8, "tipo": "flashcard", "domanda": "Funzione sociale della proprietà", "risposta": "Art. 42: la legge limita la proprietà privata per renderla accessibile a tutti e utile alla collettività."}, {"id": "c16-f7", "capitolo": "Cap. 16 – Diritti e libertà", "giorno": 8, "tipo": "flashcard", "domanda": "Diritto di sciopero (art. 40)", "risposta": "Diritto individuale a esercizio collettivo; nei servizi pubblici essenziali preavviso e prestazioni minime."}, {"id": "c16-c1", "capitolo": "Cap. 16 – Diritti e libertà", "giorno": 8, "tipo": "crocette", "domanda": "Per una riunione in luogo pubblico serve…", "risposta": "Serve il preavviso, non un'autorizzazione (art. 17).", "opzioni": ["un'autorizzazione della Questura", "un preavviso alle autorità", "nulla", "l'autorizzazione del sindaco"], "corretta": 1}, {"id": "c16-c2", "capitolo": "Cap. 16 – Diritti e libertà", "giorno": 8, "tipo": "crocette", "domanda": "Nei casi urgenti la polizia limita la libertà personale e deve comunicarlo al giudice entro…", "risposta": "Entro 48 ore; il giudice convalida nelle 48 ore successive.", "opzioni": ["24 ore", "48 ore", "72 ore", "5 giorni"], "corretta": 1}, {"id": "c16-c3", "capitolo": "Cap. 16 – Diritti e libertà", "giorno": 8, "tipo": "crocette", "domanda": "Quale diritto la Costituzione definisce espressamente «fondamentale»?", "risposta": "Art. 32: la salute è fondamentale diritto dell'individuo e interesse della collettività.", "opzioni": ["Il diritto al lavoro", "Il diritto alla salute", "Il diritto di proprietà", "Il diritto di voto"], "corretta": 1}, {"id": "c17-o1", "capitolo": "Cap. 17 – La giustizia", "giorno": 8, "tipo": "orale", "domanda": "Quali sono i principi costituzionali sulla funzione giurisdizionale?", "risposta": "La giustizia è **amministrata in nome del popolo** e i giudici sono **soggetti soltanto alla legge** (art. 101). Vale il principio del **giudice naturale precostituito per legge** (art. 25): nessuno può essere giudicato da un giudice creato dopo il fatto. C'è il **diritto di difesa**, che è **inviolabile** (art. 24). L'**art. 111** prevede il **giusto processo**: **contraddittorio**, **parità delle parti**, **giudice terzo e imparziale**, **ragionevole durata**, e l'**obbligo di motivazione** dei provvedimenti. Contro le sentenze è sempre ammesso il **ricorso in Cassazione**. È **vietato istituire nuovi giudici speciali** (art. 102) e l'**azione penale è obbligatoria** (art. 112).", "punti_chiave": ["soggetti soltanto alla legge", "giudice naturale (art. 25)", "diritto di difesa (art. 24)", "giusto processo (art. 111)", "azione penale obbligatoria"]}, {"id": "c17-o2", "capitolo": "Cap. 17 – La giustizia", "giorno": 8, "tipo": "orale", "domanda": "Che cos'è il CSM e com'è composto?", "risposta": "Il **Consiglio superiore della magistratura** garantisce l'**autonomia e l'indipendenza** della magistratura, che è **un ordine autonomo e indipendente da ogni altro potere** (art. 104). Decide su **assunzioni, trasferimenti, promozioni e provvedimenti disciplinari**, così il **Governo** non può condizionare i giudici. Ha **33 membri**. Ci sono **3 membri di diritto**: il **Presidente della Repubblica**, che lo **presiede**, il **Primo Presidente della Cassazione** e il **Procuratore generale** della Cassazione. Poi **20 togati** (cioè 2/3), eletti dai **magistrati**, e **10 laici** (cioè 1/3), eletti dal **Parlamento in seduta comune** tra professori di diritto e avvocati con 15 anni di professione. Il **vicepresidente** è un laico e i membri durano **4 anni**.", "punti_chiave": ["autonomia e indipendenza (art. 104)", "carriera e disciplina", "presieduto dal Presidente della Repubblica", "2/3 togati e 1/3 laici", "4 anni"]}, {"id": "c17-o3", "capitolo": "Cap. 17 – La giustizia", "giorno": 8, "tipo": "orale", "domanda": "Quali sono le giurisdizioni in Italia e i gradi di giudizio?", "risposta": "C'è la giurisdizione **ordinaria**, **civile** e **penale**. Nel civile si va dal **Giudice di pace o Tribunale** alla **Corte d'appello** e poi alla **Cassazione**. Nel penale si aggiungono la **Corte d'assise** e la Corte d'assise d'appello. Il **PM** sostiene l'accusa ma **non è un giudice**. Poi ci sono i **giudici speciali** previsti dalla Costituzione. Il giudice **amministrativo**: il **TAR** in primo grado e il **Consiglio di Stato** in appello. La **Corte dei conti**, per la contabilità pubblica. I **giudici tributari** e i **tribunali militari**. La **Cassazione** è il giudice di **legittimità**: non riesamina i fatti ma garantisce l'**interpretazione uniforme** della legge (la **nomofilachia**).", "punti_chiave": ["civile e penale", "tre gradi", "TAR e Consiglio di Stato", "Corte dei conti", "Cassazione e nomofilachia"]}, {"id": "c17-o4", "capitolo": "Cap. 17 – La giustizia", "giorno": 8, "tipo": "orale", "domanda": "Che cosa significano indipendenza e inamovibilità dei magistrati?", "risposta": "L'**indipendenza** significa che i magistrati non devono subire **pressioni** né dagli altri poteri né da altri magistrati: la magistratura è **autonoma e indipendente** (art. 104) e i giudici sono **soggetti soltanto alla legge** (art. 101). L'**inamovibilità** (art. 107) significa che i magistrati **non possono essere trasferiti, sospesi o dispensati** dal servizio **senza il loro consenso**, se non con un provvedimento del **CSM**, nei casi e con le garanzie di legge. Inoltre i magistrati **si distinguono solo per funzioni**: il **giudice** decide, il **PM** accusa. Si entra in magistratura **per concorso** (art. 106). Prima della Costituzione il **Governo** aveva poteri forti sulla carriera dei giudici: oggi il **ministro della Giustizia** organizza i servizi e può solo **promuovere l'azione disciplinare**.", "punti_chiave": ["indipendenza", "inamovibilità (art. 107)", "solo il CSM", "distinti solo per funzioni", "ruolo del ministro"]}, {"id": "c17-o5", "capitolo": "Cap. 17 – La giustizia", "giorno": 8, "tipo": "orale", "domanda": "Chi è il Pubblico Ministero e cosa significa l'obbligatorietà dell'azione penale?", "risposta": "Il **Pubblico Ministero** è un **magistrato** che svolge la funzione **requirente**: **indaga** e **sostiene l'accusa** nel processo penale nell'**interesse pubblico** all'accertamento dei reati. **Non è un giudice** e non difende la vittima: chiede la condanna di chi ha violato la legge, ma può anche chiedere l'assoluzione. L'**art. 112** stabilisce che il PM **ha l'obbligo di esercitare l'azione penale**: se c'è una **notizia di reato fondata**, deve procedere, e non può scegliere per ragioni politiche. Questo garantisce l'**uguaglianza** davanti alla legge e l'**indipendenza** del PM. Anche il PM è garantito dal **CSM**.", "punti_chiave": ["funzione requirente", "non è un giudice", "art. 112", "obbligatorietà", "uguaglianza e indipendenza"]}, {"id": "c17-f1", "capitolo": "Cap. 17 – La giustizia", "giorno": 8, "tipo": "flashcard", "domanda": "Giudice naturale (art. 25)", "risposta": "Nessuno può essere distolto dal giudice precostituito per legge (niente giudici creati dopo il fatto)."}, {"id": "c17-f2", "capitolo": "Cap. 17 – La giustizia", "giorno": 8, "tipo": "flashcard", "domanda": "Giusto processo (art. 111)", "risposta": "Contraddittorio, parità delle parti, giudice terzo e imparziale, ragionevole durata."}, {"id": "c17-f3", "capitolo": "Cap. 17 – La giustizia", "giorno": 8, "tipo": "flashcard", "domanda": "Inamovibilità (art. 107)", "risposta": "I magistrati non possono essere trasferiti o sospesi senza consenso, se non dal CSM nei casi di legge."}, {"id": "c17-f4", "capitolo": "Cap. 17 – La giustizia", "giorno": 8, "tipo": "flashcard", "domanda": "Nomofilachia", "risposta": "Funzione della Cassazione: garantire l'interpretazione uniforme della legge."}, {"id": "c17-f5", "capitolo": "Cap. 17 – La giustizia", "giorno": 8, "tipo": "flashcard", "domanda": "Obbligatorietà dell'azione penale (art. 112)", "risposta": "Il PM deve esercitare l'azione penale in presenza di una notizia di reato fondata."}, {"id": "c17-c1", "capitolo": "Cap. 17 – La giustizia", "giorno": 8, "tipo": "crocette", "domanda": "Chi presiede il CSM?", "risposta": "Il Presidente della Repubblica (art. 104).", "opzioni": ["Il ministro della Giustizia", "Il Primo Presidente della Cassazione", "Il Presidente della Repubblica", "Il vicepresidente laico"], "corretta": 2}, {"id": "c17-c2", "capitolo": "Cap. 17 – La giustizia", "giorno": 8, "tipo": "crocette", "domanda": "I membri laici del CSM sono eletti da…", "risposta": "Dal Parlamento in seduta comune (1/3 dei membri elettivi).", "opzioni": ["i magistrati", "il Parlamento in seduta comune", "il Governo", "il Presidente della Repubblica"], "corretta": 1}, {"id": "c17-c3", "capitolo": "Cap. 17 – La giustizia", "giorno": 8, "tipo": "crocette", "domanda": "La Corte di cassazione…", "risposta": "È il giudice di legittimità: controlla l'applicazione della legge.", "opzioni": ["riesamina i fatti della causa", "verifica la corretta applicazione della legge", "giudica le leggi incostituzionali", "è un giudice speciale"], "corretta": 1}];
